import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IPageBbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsComments";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * End-to-end test: retrieve a paginated and filtered list of comments for a specific post
 *
 * BUSINESS CONTEXT:
 *   - A user creates a post in the BBS.
 *   - Several comments and nested replies are added to that post.
 *   - Different queries/filtering options are used to list/search comments:
 *       - By author (user ID)
 *       - By parent comment (for replies only)
 *       - By date range (created_after, created_before)
 *       - Pagination (page, limit)
 *   - Checks that only the relevant comments are included in each result set, deleted comments are excluded, and pagination works as expected.
 *   - Includes queries expected to yield empty results, and the use of invalid filters.
 *
 * STEPS:
 * 1. Create a user for the test runs
 * 2. Create a post by that user
 * 3. Add multiple comments to the post (simulate several distinct comments)
 * 4. Add threaded/nested comment(s) as replies to one of the comments
 * 5. Retrieve all comments for the post, confirm count and structure
 * 6. Retrieve by author filter, confirm filtering logic
 * 7. Retrieve by parent_id filter, confirm only replies to a given comment are returned
 * 8. Retrieve by created_after / created_before (date range), ensure correct filtering
 * 9. Paginate results (limit = N, page = X), confirm slicing
 * 10. Attempt filter/queries that yield no results (e.g., non-existent author_id)
 * 11. Test with invalid filter(s) (e.g., wrong date format, non-existent parent_id, page out of range)
 */
export async function test_api_bbs_posts_comments_test_list_comments_for_post_with_various_filters(connection: api.IConnection) {
  // 1. Create a test user role (assumed exists or is provided by a helper)
  const roleId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Register the user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: "Automated E2E test user",
      role_id: roleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 3. Create a new post
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()()
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a set of comments (top-level and replies)
  const commentBodies = [
    "First comment.",
    "Second comment.",
    "Third comment.",
    "Reply to second comment.",
    "Another reply to second comment."
  ];
  const comments: bbsComments[] = [];
  for (let i = 0; i < 3; ++i) {
    const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: commentBodies[i]
      } satisfies bbsComments.ICreate
    });
    typia.assert(comment);
    comments.push(comment);
  }

  // Nested replies to 2nd comment
  const reply1 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: commentBodies[3],
      parent_id: comments[1].id,
    } satisfies bbsComments.ICreate
  });
  typia.assert(reply1);
  const reply2 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: commentBodies[4],
      parent_id: comments[1].id,
    } satisfies bbsComments.ICreate
  });
  typia.assert(reply2);
  comments.push(reply1, reply2);

  // 5. Retrieve all comments for this post, no filter
  const allResult = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {} satisfies bbsComments.IRequest
  });
  typia.assert(allResult);
  TestValidator.equals("all comments included")(allResult.pagination.records)(comments.length);

  // 6. Filter by author
  const authorResult = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {
      author_id: user.id
    } satisfies bbsComments.IRequest
  });
  typia.assert(authorResult);
  TestValidator.predicate("all author IDs match")(
    authorResult.data.every(c => c.user_id === user.id)
  );

  // 7. Filter by parent_id (replies to 2nd comment)
  const parentResult = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {
      parent_id: comments[1].id
    } satisfies bbsComments.IRequest
  });
  typia.assert(parentResult);
  TestValidator.equals("reply count")(parentResult.pagination.records)(2);
  TestValidator.predicate("all are replies to comment2")(
    parentResult.data.every(c => c.parent_id === comments[1].id)
  );

  // 8. Filter by created_after, created_before
  const allTimestamps = comments.map(c => c.created_at).sort();
  const midTimestamp = allTimestamps[Math.floor(allTimestamps.length / 2)];
  const afterResult = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_after: midTimestamp } satisfies bbsComments.IRequest,
  });
  typia.assert(afterResult);
  TestValidator.predicate("created_after filter")(
    afterResult.data.every(c => c.created_at > midTimestamp)
  );

  const beforeResult = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_before: midTimestamp } satisfies bbsComments.IRequest,
  });
  typia.assert(beforeResult);
  TestValidator.predicate("created_before filter")(
    beforeResult.data.every(c => c.created_at < midTimestamp)
  );

  // 9. Pagination - limit 2 per page
  const paged1 = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { limit: 2, page: 1 } satisfies bbsComments.IRequest
  });
  typia.assert(paged1);
  TestValidator.equals("page 1 size")(paged1.data.length)(2);
  TestValidator.equals("page 1 number")(paged1.pagination.current)(1);
  const paged2 = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { limit: 2, page: 2 } satisfies bbsComments.IRequest
  });
  typia.assert(paged2);
  TestValidator.equals("page 2 size")(paged2.data.length)(2);
  TestValidator.equals("page 2 number")(paged2.pagination.current)(2);
  // last page, should have 1 or 2 depending on odd/even
  const paged3 = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { limit: 2, page: 3 } satisfies bbsComments.IRequest
  });
  typia.assert(paged3);
  TestValidator.predicate("last page size valid")(paged3.data.length <= 2);

  // 10. Empty result: non-existent author
  const bogusAuthor = typia.random<string & tags.Format<"uuid">>();
  const noneByAuthor = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { author_id: bogusAuthor } satisfies bbsComments.IRequest
  });
  typia.assert(noneByAuthor);
  TestValidator.equals("empty data for bogus author")(noneByAuthor.data.length)(0);

  // 11. Invalid filter: non-existent parent_id
  const bogusParentId = typia.random<string & tags.Format<"uuid">>();
  const noneByParent = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { parent_id: bogusParentId } satisfies bbsComments.IRequest
  });
  typia.assert(noneByParent);
  TestValidator.equals("empty data for bogus parent_id")(noneByParent.data.length)(0);

  // 12. Edge case: invalid format for date
  TestValidator.error("invalid date format should error")(async () => {
    await api.functional.bbs.posts.comments.patchByPostid(connection, {
      postId: post.id,
      body: { created_after: "not-a-date" as any } as any
    });
  });
}

