import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * E2E: Fetching a single comment's details by comment ID for a given post.
 *
 * This test verifies the following business rules and API behaviors:
 *
 * 1. Register a user, create a post, and add a comment as that user.
 * 2. Directly retrieve the comment details by its ID under the correct post and verify that all required fields (content, author, timestamps, parent relations) are properly populated and correspond to the input data.
 * 3. Attempt to retrieve a comment with a random UUID (doesn't exist) and confirm that a not-found error is thrown (runtime business error).
 * 4. Register a second user; re-fetch the original comment (should be public); verify it is returned and fields match.
 * 5. (Robustness): Try fetching a valid comment ID, but with a mismatched postId — expect not-found error because the relation doesn't match.
 *
 * This scenario ensures correct retrieval, business validation, error semantics, and public accessibility of comments on public posts.
 */
export async function test_api_bbs_test_get_single_comment_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new user who is the author of the post/comment
  const user_role_id: string = typia.random<string & tags.Format<"uuid">>();
  const author_email: string = typia.random<string & tags.Format<"email">>();
  const author_username: string = RandomGenerator.name();
  const author_password: string = RandomGenerator.alphaNumeric(12);
  const user1 = await api.functional.bbs.users.post(connection, {
    body: {
      username: author_username,
      email: author_email,
      password: author_password,
      role_id: user_role_id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user1);

  // 2. Create a new post under that user
  const category_id: string = typia.random<string & tags.Format<"uuid">>();
  const post_title = RandomGenerator.paragraph()();
  const post_content = RandomGenerator.content()()();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id,
      title: post_title,
      content: post_content,
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("post.user_id")(post.user_id)(user1.id);

  // 3. Add a comment to the post as user1
  const comment_content = RandomGenerator.paragraph()();
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: comment_content,
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment.post_id")(comment.post_id)(post.id);
  TestValidator.equals("comment.user_id")(comment.user_id)(user1.id);
  TestValidator.equals("comment.content")(comment.content)(comment_content);

  // 4. Retrieve the comment by (postId, commentId)
  const fetched = await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched.id")(fetched.id)(comment.id);
  TestValidator.equals("fetched.post_id")(fetched.post_id)(post.id);
  TestValidator.equals("fetched.content")(fetched.content)(comment_content);
  TestValidator.equals("fetched.user_id")(fetched.user_id)(user1.id);
  TestValidator.equals("fetched.parent_id")(fetched.parent_id ?? null)(null);
  TestValidator.equals("fetched.deleted_at")(fetched.deleted_at ?? null)(null);
  TestValidator.predicate("created_at format")(typeof fetched.created_at === "string");
  TestValidator.predicate("updated_at format")(typeof fetched.updated_at === "string");

  // 5. Try fetching a non-existent comment ID — must throw not found
  const random_comment_id: string = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetching non-existent comment should error")(async () => {
    await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
      postId: post.id,
      id: random_comment_id,
    });
  });

  // 6. Register a second user and simulate public access
  const user2_email: string = typia.random<string & tags.Format<"email">>();
  const user2_username: string = RandomGenerator.name();
  const user2_password: string = RandomGenerator.alphaNumeric(12);
  const user2_role_id: string = typia.random<string & tags.Format<"uuid">>();
  const user2 = await api.functional.bbs.users.post(connection, {
    body: {
      username: user2_username,
      email: user2_email,
      password: user2_password,
      role_id: user2_role_id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user2);
  // (No authentication API, but in a real scenario, we'd switch context)

  // Fetch the comment as user2; should succeed and have the same data
  const fetched2 = await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });
  typia.assert(fetched2);
  TestValidator.equals("fetched2.id")(fetched2.id)(comment.id);
  TestValidator.equals("fetched2.post_id")(fetched2.post_id)(post.id);
  TestValidator.equals("fetched2.content")(fetched2.content)(comment_content);

  // 7. Robustness: Fetch with valid comment ID but unrelated postId
  const wrong_post_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetching comment with unrelated postId should fail")(async () => {
    await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
      postId: wrong_post_id,
      id: comment.id,
    });
  });
}

