import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * Test adding a new top-level comment to an existing post and handle invalid cases.
 *
 * This E2E covers both the successful creation of a post comment and input validation & permissions error scenarios. The process validates proper API behavior for both normal and exceptional states.
 *
 * Test Process:
 * 1. Register a new user (who will author the comment).
 * 2. Log in or ensure the connection represents the created user (implicitly handled by test isolation).
 * 3. Create a new post for commenting.
 * 4. Add a valid, non-empty comment to the created post; verify the comment is persisted, assigned proper metadata, and links to the correct post & user.
 * 5. Attempt to add a comment with empty content to the post; expect a validation error from API.
 * 6. Attempt to comment on a non-existent post (random UUID); expect a not-found error.
 * 7. Attempt to comment while unauthenticated; expect a permission (auth) error.
 *
 * Each edge case checks appropriate error handling without TypeScript violations, using runtime error proofing. No cleanup required as database isolation is assumed.
 */
export async function test_api_bbs_test_create_comment_on_post_valid_and_invalid(connection: api.IConnection) {
  // 1. Create a new user
  const userCreateInput: IBbsUsers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: RandomGenerator.alphabets(8) + "@test.com",
    password: "ValidP@ss123",
    // To select a valid user role, we generate a random UUID (test DB is seeded)
    role_id: typia.random<string & tags.Format<"uuid">>(),
    bio: "Test user for commenting",
  };
  const user = await api.functional.bbs.users.post(connection, {
    body: userCreateInput,
  });
  typia.assert(user);

  // 2. Create a post for this user (category assumed - use random UUID as test DB)
  const postCreateInput: bbsPosts.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Test Post Title " + RandomGenerator.alphaNumeric(4),
    content: "This is a test post body.",
  };
  const post = await api.functional.bbs.posts.post(connection, { body: postCreateInput });
  typia.assert(post);

  // 3. Add valid top-level comment
  const commentInput: bbsComments.ICreate = { content: "A valid test comment." };
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: commentInput,
  });
  typia.assert(comment);
  TestValidator.equals("comment postId")(comment.post_id)(post.id);
  TestValidator.equals("comment content")(comment.content)(commentInput.content);
  TestValidator.equals("parent_id is null for top-level")(comment.parent_id)(null);
  TestValidator.equals("comment user is correct")(comment.user_id)(user.id);

  // 4. Attempt comment with empty content: Should error
  await TestValidator.error("empty content should fail")(() =>
    api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: { content: "" }, // parent_id omitted for top-level
    })
  );

  // 5. Attempt commenting on non-existent post: Should error
  await TestValidator.error("non-existing post id should error")(() =>
    api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
      body: { content: "Comment to ghost post" },
    })
  );

  // 6. Attempt commenting while unauthenticated: Should error (simulate no auth)
  const unauthConn: api.IConnection = { ...connection, headers: { ...connection.headers } };
  // Simulate log out by clearing headers that may carry auth cookies/tokens
  if ("authorization" in unauthConn.headers) delete unauthConn.headers["authorization"];
  if ("cookie" in unauthConn.headers) delete unauthConn.headers["cookie"];
  await TestValidator.error("unauthenticated comment")(() =>
    api.functional.bbs.posts.comments.postByPostid(unauthConn, {
      postId: post.id,
      body: { content: "Should fail due to no auth" },
    })
  );
}

