  /**
   * Main content/body of the post, from the `content` field in the posts
   * table.
   *
   * Includes long-form text, opinion, or analysis. Critical for community
   * discussion.
   */
  content: string;

  /**
   * The timestamp when the post was created, matching `created_at` in the
   * database.
   *
   * Displayed in lists, used for freshness ordering, and necessary for
   * audits.
   */
