import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * Test updating a BBS post comment and enforcement of permissions/validation.
 *
 * 1. Create user role IDs for normal members (mocked/randomised for test).
 * 2. Create user1 (author) and user2 (non-author) with distinct profiles.
 * 3. User1 creates a post.
 * 4. User1 adds a comment to the post.
 * 5. User1 successfully updates their own comment: content changes and updated_at
timestamp is refreshed.
 * 6. User2 attempts to update user1's comment and receives a permission error.
 * 7. Validation error: User1 attempts update with empty content.
 * 8. Soft-delete the comment (simulate as direct field manipulation, since no API is provided for deletion), then attempt update (expect failure).
 * 9. Attempt to update a non-existent comment ID and verify error.
 */
export async function test_api_bbs_test_update_comment_content_owner_and_permission(
  connection: api.IConnection,
) {
  // 1. Prepare random role IDs to be used for test users.
  const roleId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Register two users (author and non-author)
  const user1Data = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234-User1!",
    role_id: roleId,
  } satisfies IBbsUsers.ICreate;

  const user1 = await api.functional.bbs.users.post(connection, { body: user1Data });
  typia.assert(user1);

  const user2Data = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234-User2!",
    role_id: roleId,
  } satisfies IBbsUsers.ICreate;

  const user2 = await api.functional.bbs.users.post(connection, { body: user2Data });
  typia.assert(user2);

  // 3. User1 creates a post in a random category.
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    }
  });
  typia.assert(post);

  // 4. User1 adds a comment to their post.
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "This is an original comment by user1."
    },
  });
  typia.assert(comment);
  const originalUpdatedAt = comment.updated_at;

  // 5. Author successfully updates their own comment.
  const updatedContent = "Editing the comment as user1 (author).";
  const updatedComment = await api.functional.bbs.posts.comments.putByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
    body: {
      content: updatedContent,
    },
  });
  typia.assert(updatedComment);
  TestValidator.equals("comment content was updated")(updatedComment.content)(updatedContent);
  TestValidator.notEquals("updated_at changed after edit")(updatedComment.updated_at)(originalUpdatedAt);

  // 6. Non-author tries to update the comment (should be forbidden)
  // (Assume switching session via re-registration is enough for test context)
  // No formal session switch, as users are separate already
  await TestValidator.error("user2 cannot update someone else's comment")(
    async () => {
      await api.functional.bbs.posts.comments.putByPostidAndId(connection, {
        postId: post.id,
        id: comment.id,
        body: {
          content: "User2 attempts unauthorized edit",
        },
      });
    }
  );

  // 7. Author tries to update with empty content (should get validation error)
  await TestValidator.error("comment update with empty content should fail")(
    async () => {
      await api.functional.bbs.posts.comments.putByPostidAndId(connection, {
        postId: post.id,
        id: comment.id,
        body: {
          content: "",
        },
      });
    }
  );

  // 8. Try to update a soft-deleted comment (simulate by reusing comment_id and mocking deletion state; skip actual API call, as no endpoint exists yet)
  // Not implementable as no API exists for deletion or direct deletion-state assignment.

  // 9. Update a non-existent comment (random UUID). Should result in error
  await TestValidator.error("update non-existent comment id")(
    async () => {
      await api.functional.bbs.posts.comments.putByPostidAndId(connection, {
        postId: post.id,
        id: typia.random<string & tags.Format<"uuid">>(), // random UUID unlikely to exist
        body: {
          content: "Trying to update non-existent comment",
        },
      });
    }
  );
}

