   * UUID of the user (author) who created this post, corresponding to
   * `user_id` in the posts table.
   *
   * Provides author traceability and links to user profiles.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * UUID of the category under which the post was published, referencing
