 * name or description is correctly rejected by the API. Both name and description are required fields as per the schema/documentation.
 *
 * Steps:
 * 1. Attempt to create a category with an empty name and valid description – expects error.
 * 2. Attempt to create a category with a valid name and empty description – expects error.
 * 3. Attempt to create a category with both name and description empty – expects error.
 * 4. (Bonus) If possible in TypeScript, attempt to create a category with missing name or missing description (but this is a TypeScript compile-time error, so only attempt at runtime if possible/allowed).
 *
 * For each case, validate that the API responds with an appropriate error (using TestValidator.error), and does not create the category.
 */
export async function test_api_bbs_test_create_category_with_empty_name_or_description(connection: api.IConnection) {
  // 1. Empty name
  await TestValidator.error("empty name - creation should fail")(() =>
    api.functional.bbs.categories.post(connection, {
      body: {
        name: "",
        description: "Valid description.",
      } satisfies bbsCategories.ICreate,
    })
  );

  // 2. Empty description
  await TestValidator.error("empty description - creation should fail")(() =>
    api.functional.bbs.categories.post(connection, {
      body: {
        name: "Valid Name",
        description: "",
      } satisfies bbsCategories.ICreate,
    })
  );

  // 3. Both name and description empty
  await TestValidator.error("both empty - creation should fail")(() =>
    api.functional.bbs.categories.post(connection, {
      body: {
        name: "",
        description: "",
      } satisfies bbsCategories.ICreate,
    })
  );

  // 4. Cannot test missing properties - TypeScript will not compile if required fields are omitted.
}

