/**
 * Validate uniqueness constraint in category name when updating.
 *
 * This test ensures the API enforces unique category names by preventing updates that would create duplicates. Categories in a BBS are organizational tools that must be uniquely identifiable by their names. Administrators must not be able to rename categories to names already in use.
 *
 * Workflow:
 * 1. Create the first category (categoryA) with a unique name.
 * 2. Create a second category (categoryB) with a different unique name.
 * 3. Attempt to update the second category (categoryB) so its name matches that of the first (categoryA).
 * 4. The API should return a validation error, not allowing the update due to the name collision.
 *
 * This test validates that the system prevents administrative mistakes (or attacks) that would result in ambiguous or duplicate topic organization, ensuring integrity of board structure.
 */
export async function test_api_bbs_test_update_category_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. Create the first category (categoryA) with a unique name
  const categoryAInput: bbsCategories.ICreate = {
    name: `A-` + RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(1),
  };
  const categoryA: bbsCategories = await api.functional.bbs.categories.post(
    connection,
    {
      body: categoryAInput,
    },
  );
  typia.assert(categoryA);

  // 2. Create the second category (categoryB) with a different unique name
  const categoryBInput: bbsCategories.ICreate = {
    name: `B-` + RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(1),
  };
  const categoryB: bbsCategories = await api.functional.bbs.categories.post(
    connection,
    {
      body: categoryBInput,
    },
  );
  typia.assert(categoryB);

  // 3. Attempt to update the second category to have the same name as the first
  const duplicateNameUpdate: bbsCategories.IUpdate = {
    name: categoryAInput.name, // duplicate name
    description: RandomGenerator.paragraph()(1), // Description is valid, name is not
  };

  // 4. API should reject the operation due to name uniqueness constraint
  await TestValidator.error("category name must be unique")(async () => {
    await api.functional.bbs.categories.putById(
      connection,
      {
        id: categoryB.id,
        body: duplicateNameUpdate,
      },
    );
  });
}

