import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate category deletion handling when dependent posts exist.
 *
 * This test ensures that a category cannot be deleted if there are posts still referencing it,
 * enforcing business and referential integrity rules on the board.
 *
 * Steps:
 * 1. Create a new discussion category.
 * 2. Register a user who will author a dependent post (since post creation requires authentication).
 * 3. Have the user create a post assigned to the new category (thus creating a referential dependency).
 * 4. Attempt to delete the category while it is still referenced by an existing post.
 *    The API should reject this attempt, returning a conflict/dependency error rather than deleting the category.
 * 5. Verify that an error occurs (test passes if deletion is blocked, fails if succeeds).
 */
export async function test_api_bbs_test_delete_category_with_dependent_posts(
  connection: api.IConnection,
) {
  // 1. Create a new category
  const categoryName = RandomGenerator.alphabets(10);
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 2. Register a new user (simulate member role via a random uuid for the role_id)
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "securePassword1!",
      bio: RandomGenerator.paragraph()(),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 3. Create a post referencing the category (simulate as created by the user)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Attempt to delete the category -- should fail due to post dependency
  await TestValidator.error("Category deletion should fail due to post dependency")(
    async () => {
      await api.functional.bbs.categories.eraseById(connection, { id: category.id });
    },
  );
}

