import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing user roles with valid pagination and search filters.
 *
 * This test ensures the user role listing endpoint can search and paginate correctly, and only returns user role metadata (never user data).
 *
 * Steps:
 * 1. Create at least three distinct user roles with unique names and descriptions (to enable effective search/filter tests).
 * 2. Perform a paginated search listing with a partial "name" and/or "description" filter corresponding to one of the created roles.
 * 3. Verify the response contains only user role records whose names or descriptions match the filter used.
 * 4. Verify the response pagination counts, records and pages fields for correctness.
 * 5. Ensure no user-personal data is present in the result; only user role metadata should be returned.
 */
export async function test_api_bbs_test_list_user_roles_with_valid_pagination_and_search(connection: api.IConnection) {
  // 1. Create at least three distinct user roles
  const role1 = await api.functional.bbs.userRoles.post(connection, { body: { name: "auditor-" + RandomGenerator.alphaNumeric(6), description: "First test role for search" } satisfies IBbsUserRoles.ICreate });
  typia.assert(role1);
  const role2 = await api.functional.bbs.userRoles.post(connection, { body: { name: "moderator-" + RandomGenerator.alphaNumeric(6), description: "Second test role for pagination" } satisfies IBbsUserRoles.ICreate });
  typia.assert(role2);
  const role3 = await api.functional.bbs.userRoles.post(connection, { body: { name: "helper-" + RandomGenerator.alphaNumeric(6), description: "Third test role has unique text" } satisfies IBbsUserRoles.ICreate });
  typia.assert(role3);

  // 2. Perform paginated search using partial "name" filter for role2
  const pageLimit = 2;
  const result = await api.functional.bbs.userRoles.patch(connection, { body: { page: 1, limit: pageLimit, name: role2.name.slice(0, 5), description: null } satisfies IBbsUserRoles.IRequest });
  typia.assert(result);

  // 3. Ensure only roles with matching names are returned
  for (const returned of result.data) {
    TestValidator.predicate(`Returned role name includes search filter`) (returned.name.includes(role2.name.slice(0, 5)));
  }

  // 4. Check that pagination metadata fields are correct
  TestValidator.predicate("Pagination limit respected") (result.pagination.limit === pageLimit);
  TestValidator.predicate("Current page is 1") (result.pagination.current === 1);
  TestValidator.predicate("Records field is correct") (result.pagination.records >= 1);
  TestValidator.predicate("Pages count matches records/limit") (result.pagination.pages === Math.ceil(result.pagination.records / pageLimit));

  // 5. Validate response contains only user role metadata fields (id, name, description)
  for (const returned of result.data) {
    TestValidator.equals("User role metadata: only id, name, description")(Object.keys(returned).sort()) (["description", "id", "name"]);
  }
}

