import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validates retrieval of a user role's metadata by UUID.
 *
 * This test ensures that after creating a new user role, it can be retrieved by its UUID and all metadata (name, description, id) matches the originally supplied payload. No user information should be disclosed—only role metadata is returned as per design. This ensures the /bbs/userRoles/{id} endpoint is correctly implemented and meets business/audit requirements.
 *
 * Test Steps
 * 1. Create a new user role via POST /bbs/userRoles. Capture the returned (id, name, description).
 * 2. Retrieve the same role via GET /bbs/userRoles/{id} using the UUID from step 1.
 * 3. Assert that the metadata (id, name, description) in the GET response match the POST payload and no user-specific information is present in the response.
 */
export async function test_api_bbs_userRoles_getById(connection: api.IConnection) {
  // 1. Create a new user role
  const createPayload = {
    name: `role_${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(),
  } satisfies IBbsUserRoles.ICreate;
  const created: IBbsUserRoles = await api.functional.bbs.userRoles.post(connection, {
    body: createPayload,
  });
  typia.assert(created);

  // 2. Retrieve the role by its ID
  const found: IBbsUserRoles = await api.functional.bbs.userRoles.getById(connection, {
    id: created.id,
  });
  typia.assert(found);

  // 3. Validate that all metadata matches and no user info is present
  TestValidator.equals("role id matches")(found.id)(created.id);
  TestValidator.equals("role name matches")(found.name)(createPayload.name);
  TestValidator.equals("role description matches")(found.description)(createPayload.description);
}

