import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test robust error handling and security of user role retrieval by ID
 *
 * This test attempts to fetch a user role with two types of invalid input:
 * 1. An ID with an invalid format (not a valid UUID)
 * 2. A well-formed UUID, but not present in the system (non-existent role)
 *
 * Both attempts should result in a not-found error (or input validation error for the invalid UUID), with no role data leaked in the response.
 *
 * Steps:
 * 1. Attempt to fetch a user role using an obviously invalid ID (e.g., 'not-a-uuid'). Expect a validation error with no data leaked.
 * 2. Attempt to fetch a user role using a well-formed, random UUID that does not exist in the system. Expect a not-found error, with no role information returned.
 * 3. Confirm that in both error cases, no role metadata is returned in the API response.
 */
export async function test_api_bbs_userRoles_getById_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Attempt to fetch with an invalid UUID format
  await TestValidator.error("invalid UUID format should fail")(
    async () => {
      // Using an obviously invalid string instead of a UUID
      await api.functional.bbs.userRoles.getById(connection, {
        id: "not-a-uuid" as string & tags.Format<"uuid">,
      });
    },
  );

  // 2. Attempt to fetch with a well-formed, but non-existent UUID
  await TestValidator.error("non-existent UUID should result in not-found error")(
    async () => {
      // Generate a random UUID, very unlikely to exist in the DB
      await api.functional.bbs.userRoles.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

