import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate the creation of a new user role with valid, unique data.
 *
 * Business context:
 * This test ensures an administrator can successfully create a user role in the system by providing a unique name and a descriptive text. The role should be immediately available for assignment/listing after creation, and all fields should match the provided input.
 *
 * Steps:
 * 1. Prepare a unique role name and a meaningful description
 * 2. As an administrator, call the create user role API endpoint
 * 3. Verify the response: the returned role's name and description match the input, and an ID (uuid) is returned
 * 4. (Optional) The role should be available for listing and assignment, but this will not be tested here unless a listing endpoint is provided
 */
export async function test_api_bbs_test_create_user_role_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare payload: unique role name and description
  const uniqueRoleName = `role_${typia.random<string>()}`;
  const description = "Role for content moderators with extended permissions.";
  const payload = {
    name: uniqueRoleName,
    description,
  } satisfies IBbsUserRoles.ICreate;

  // 2. Call create user role API
  const createdRole = await api.functional.bbs.userRoles.post(connection, {
    body: payload,
  });
  typia.assert(createdRole);

  // 3. Validate response fields
  TestValidator.equals("role name matches")(createdRole.name)(uniqueRoleName);
  TestValidator.equals("role description matches")(createdRole.description)(description);
  TestValidator.predicate("role ID is a valid UUID")(
    typeof createdRole.id === "string" &&
      /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(createdRole.id),
  );
}

