/**
 * Validate duplicate user role name error handling for user role creation API.
 *
 * This test ensures that attempting to create a new user role with a name that already exists
 * results in a validation or conflict error, enforcing the uniqueness constraint for the `name` field.
 * This enforces business rules preventing overlapping or redundant permission roles in the platform.
 *
 * Steps:
 * 1. Create a user role with a unique name and description
 * 2. Attempt to create another user role with the same name but different description
 * 3. Assert that the first creation succeeds and returns a valid user role
 * 4. Assert that the second attempt fails with a validation (duplicate/conflict) error
 */
export async function test_api_bbs_test_create_user_role_with_duplicate_name(
  connection: api.IConnection,
) {
  // Step 1: Create a new user role with a unique name
  const uniqueRoleName = RandomGenerator.alphaNumeric(12);
  const initialRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: uniqueRoleName,
      description: RandomGenerator.paragraph()(),
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(initialRole);
  TestValidator.equals("created role name matches")(initialRole.name)(uniqueRoleName);

  // Step 2: Attempt to create a second user role with the same name but different description
  await TestValidator.error("duplicate user role creation should throw")(
    async () => {
      await api.functional.bbs.userRoles.post(connection, {
        body: {
          name: uniqueRoleName, // duplicate
          description: RandomGenerator.paragraph()(),
        } satisfies IBbsUserRoles.ICreate,
      });
    },
  );
}

