        // (this is the only circumstance allowed to test runtime validation)
        // @ts-expect-error
        await api.functional.bbs.userRoles.post(connection, { body });
      },
    );
  };

  // 1. Missing `name`
  await postInvalid({ description: "Moderator manages post queries." });

  // 2. Missing `description`
  await postInvalid({ name: "moderator" });

  // 3. Both fields missing
  await postInvalid({});

  // 4. Empty strings for both fields
  await postInvalid({ name: "", description: "" });

  // 5. Empty string for `name` only
  await postInvalid({ name: "", description: "Grants access to advanced functions." });

  // 6. Empty string for `description` only
  await postInvalid({ name: "contributor", description: "" });
}

