    connection,
    {
      body: createInput,
    },
  );
  typia.assert(createdRole);

  // 2. Update the role's name and description
  const updateInput: IBbsUserRoles.IUpdate = {
    name: `updated_role_${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(),
  };
  const updatedRole: IBbsUserRoles = await api.functional.bbs.userRoles.putById(
    connection,
    {
      id: createdRole.id,
      body: updateInput,
    },
