  // 3. Validate that the role metadata reflects the update
  TestValidator.equals("updated id remains the same")(updatedRole.id)(createdRole.id);
  TestValidator.equals("role name updated")(updatedRole.name)(updateInput.name);
  TestValidator.equals("role description updated")(updatedRole.description)(updateInput.description);
}

