import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that updating a user role with invalid data produces the correct error handling and leaves the record unchanged.
 *
 * - Business Context: Modifying user role metadata is a privilege for admins, and robust validation is required to ensure platform governance, especially for fields like 'name' and 'description'. Attempting to pass invalid types or empty strings must be rejected, with no change to existing role details.
 *
 * Steps:
 * 1. Create a valid user role using random name and description
 * 2. Attempt to update it with invalid payloads, namely:
 *    (a) Empty string for name and/or description
 *    (b) null for name and/or description (null is allowed, so skip this part if it just means 'unset')
 *    (c) wrong data types (e.g. number for name)
 *    (d) Both fields omitted (acceptable if partial update is no-op, but mention test is focused on invalid data)
 * 3. For each invalid attempt:
 *    a. Confirm that an error is thrown (TestValidator.error)
 *    b. Read the user role and assert it was not changed
 */
export async function test_api_bbs_test_update_user_role_with_invalid_data(connection: api.IConnection) {
  // 1. Create a valid user role
  const initial = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(initial);

  // 2. Attempt update with empty string 'name'
  TestValidator.error("empty string for name should fail")(async () => {
    await api.functional.bbs.userRoles.putById(connection, {
      id: initial.id,
      body: {
        name: "",
      },
    });
  });
  // 3. Confirm role unchanged
  const afterEmptyName = await api.functional.bbs.userRoles.putById(connection, { id: initial.id, body: {} });
  TestValidator.equals("name unchanged")(afterEmptyName.name)(initial.name);
  TestValidator.equals("description unchanged")(afterEmptyName.description)(initial.description);

  // 4. Attempt update with empty string 'description'
  TestValidator.error("empty string for description should fail")(async () => {
    await api.functional.bbs.userRoles.putById(connection, {
      id: initial.id,
      body: {
        description: "",
      },
    });
  });
  const afterEmptyDesc = await api.functional.bbs.userRoles.putById(connection, { id: initial.id, body: {} });
  TestValidator.equals("name unchanged")(afterEmptyDesc.name)(initial.name);
  TestValidator.equals("description unchanged")(afterEmptyDesc.description)(initial.description);

  // 5. Attempt with number as name (type error)
  TestValidator.error("number for name should fail")(async () => {
