 * Test Workflow:
 * 1. Create a valid user role (random name, description)
 * 2. Attempt to update it using invalid payloads:
 *    a. Update with an empty string for 'name'
 *    b. Update with an empty string for 'description'
 *    c. Update with an invalid data type (number) for 'name'
 *    d. Update with an invalid data type (number) for 'description'
 * 3. For each invalid attempt: (a) Confirm error is thrown (TestValidator.error); (b) Confirm the user role is unchanged after the failed update.
 */
export async function test_api_bbs_test_update_user_role_with_invalid_data(connection: api.IConnection) {
