  const initial = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(initial);

  // 2a. Attempt to update with empty string as name
  await TestValidator.error("empty string for name should fail")(
    async () => {
      await api.functional.bbs.userRoles.putById(connection, {
        id: initial.id,
        body: { name: "" },
      });
    }
  );
  // Confirm unchanged
  const afterName = await api.functional.bbs.userRoles.putById(connection, {
    id: initial.id,
    body: {}, // no update
  });
  TestValidator.equals("name unchanged after empty name fail")(afterName.name)(initial.name);
  TestValidator.equals("description unchanged after empty name fail")(afterName.description)(initial.description);

  // 2b. Attempt to update with empty string as description
  await TestValidator.error("empty string for description should fail")(
    async () => {
      await api.functional.bbs.userRoles.putById(connection, {
        id: initial.id,
        body: { description: "" },
      });
    }
  );
  // Confirm unchanged again
  const afterDesc = await api.functional.bbs.userRoles.putById(connection, {
    id: initial.id,
    body: {},
  });
  TestValidator.equals("name unchanged after empty description fail")(afterDesc.name)(initial.name);
  TestValidator.equals("description unchanged after empty description fail")(afterDesc.description)(initial.description);

  // 2c. Attempt to update with number as name (type error)
  await TestValidator.error("number for name should fail")(
    async () => {
      await api.functional.bbs.userRoles.putById(connection, {
        id: initial.id,
        body: { name: 12345 as any }, // purposely invalid type
      });
