/**
 * User role metadata record.
 *
 * Implements the business logic of platform roles as described in requirements
 * and user_roles table.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IBbsUserRoles = {
  /**
   * Unique identifier for user role (UUID).
   *
   * Primary key from user_roles.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Unique label for the user role (e.g., member, moderator, administrator).
   *
   * Fulfills role business logic and governance, per requirements.
   */
  name: string;

  /**
   * Detailed explanation of the role's permissions, scope, or duties.
   *
   * Shown in onboarding and administration to explain role scope.
   */
  description: string;
};
export namespace IBbsUserRoles {
  /**
   * Payload to create a new user role.
   *
   * Used for onboarding/registration configuration and extending
   * moderation/business model, as per requirements and schema.
   */
  export type ICreate = {
    /**
     * Role label (unique, required).
     *
     * Required for creating new permissions classes in system governance.
     */
    name: string;

    /**
     * Human-readable explanation of the role's authority and purpose.
     *
     * For oversight and onboarding display.
     */
    description: string;
  };

  /**
   * Payload to update an existing role.
   *
   * All fields optional for PUT/PATCH behaviors, as per requirements analysis
   * and schema comments.
   */
  export type IUpdate = {
    /**
     * New name/label for user role, if changing.
     *
     * Must remain unique if provided.
     */
    name?: string | null;

    /**
     * Updated explanation for the role (e.g., changing duties, scope).
     *
     * Administrative update only.
     */
    description?: string | null;
  };
}

