import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that updating a user role requires proper authorization.
 * 
 * This test ensures that the update user role API endpoint enforces authentication and permissions. 
 * It attempts to update a user role without a valid or privileged authentication token, expecting the operation to fail due to insufficient permissions.
 * 
 * Step-by-step process:
 * 1. Create a user role as a dependency (with required privileges).
 * 2. Attempt to update the created user role without providing authentication, or as an unauthorized user.
 * 3. Confirm that the API rejects the attempt with an appropriate permission error.
 */
export async function test_api_bbs_test_update_user_role_requires_authorization(connection: api.IConnection) {
  // 1. Create a user role with valid (admin) privileges to set up the scenario
  const role = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()()
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(role);

  // 2. Create a new unauthenticated connection (remove token/header)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers["Authorization"];

  // 3. Attempt to update the role with no authentication
  await TestValidator.error("should reject update without auth")(
    async () => {
      await api.functional.bbs.userRoles.putById(unauthConnection, {
        id: role.id,
        body: {
          name: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()()
        } satisfies IBbsUserRoles.IUpdate,
      });
    }
  );
}

