import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate administrator-initiated deactivation (soft-delete) of a user role, including audit trace verification.
 *
 * This test ensures that when a privileged user (administrator) deactivates a user role, the operation performs a soft-delete rather than physical removal. The metadata and audit trail must remain intact to satisfy auditability and compliance requirements.
 *
 * Workflow:
 * 1. Create a user role via the official user role creation endpoint (to set up test conditions)
 * 2. Deactivate the role (soft-delete) via the eraseById endpoint with the new role’s UUID
 * 3. Validate:
 *    - The role is not physically deleted, but is marked as inactive/deleted or similar
 *    - Key metadata (e.g., id, name, description) remains and matches original
 *    - If available, meta fields (created_at, updated_at, etc.) remain unaltered except as needed
 *    - Any soft-delete specific indicator is true/filled/broken as per business rules
 *    - The operation does not affect unrelated roles
 *
 * Note: Since the API only returns the (possibly inactive) role and the schema does not expose a deleted/active field, this test will validate that the record still exists and essential information is unchanged post-deactivation.
 */
export async function test_api_bbs_test_delete_user_role_success_and_audit(
  connection: api.IConnection,
) {
  // 1. Create a user role
  const originalRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(3),
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(originalRole);

  // 2. Soft-delete (deactivate) the user role
  const erasedRole = await api.functional.bbs.userRoles.eraseById(connection, {
    id: originalRole.id,
  });
  typia.assert(erasedRole);

  // 3. Audit remaining metadata. The record should still exist, although business state may be updated internally.
  TestValidator.equals("role id retained")(erasedRole.id)(originalRole.id);
  TestValidator.equals("name retained")(erasedRole.name)(originalRole.name);
  TestValidator.equals("description retained")(erasedRole.description)(originalRole.description);
}

