    /**
     * Number of vote records per page. Default is 100. Controls batch size
     * returned. See IPage.IRequest.
     */
    limit?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "uint32";
          }>)
      | null;

    /**
     * Filter by the voter's (user's) UUID. Useful for auditing or personal
     * history views. From votes.user_id.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Filter by a specific post (UUID) - returns votes associated with the
     * given post ID. From votes.post_id.
     */
    post_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Filter votes associated with a particular comment (UUID). Enables
     * lookup of votes for a comment thread/reply (votes.comment_id).
     */
    comment_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Filter by vote value: +1 (upvote) or -1 (downvote). Optional. From
     * votes.value.
     */
    value?: -1 | 1 | null;

    /**
     * Include votes created after this date/time (ISO-8601).
     * Audit/analytics tool.
     */
    created_after?: (string & tags.Format<"date-time">) | null;

    /**
     * Include votes created before this date/time (ISO-8601).
     * Audit/analytics/periodic analysis.
     */
    created_before?: (string & tags.Format<"date-time">) | null;
  };

  /**
   * Object for creating a vote on a post or comment.
   *
   * Specifies the target entity (post_id or comment_id) and the value
   * (+1/-1). Enforces one-vote-per-target-per-user as described in
   * requirements and Prisma schema.
   */
  export type ICreate = {
    /**
     * ID of the post to be voted on. Set this or comment_id, but not both.
     * Enforced by business logic and unique constraint (see
     * votes.post_id).
     */
    post_id?: (string & tags.Format<"uuid">) | null;

    /**
     * ID of the comment to be voted on. Set this or post_id, but not both.
     * Only one target can be set. From votes.comment_id.
     */
    comment_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Required. Vote value: +1 (upvote) or -1 (downvote). Enforced by
     * schema and business rules.
     */
    value: -1 | 1;
  };
}

