import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";
import type { IPageIBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of votes with pagination (admin workflow).
 *
 * This test simulates a full admin-side audit and analytics workflow for votes in the BBS system.
 * It ensures that advanced vote query, filtering, and pagination logic works as intended, returning precisely
 * the correct set and no extraneous data.
 *
 * Steps:
 * 1. Create admin and multiple regular user accounts.
 * 2. Create several posts with different user authors.
 * 3. Add comments on the posts by various users.
 * 4. Each user votes both up and down on a variety of posts and comments, including self-voting.
 * 5. As admin, fetch paginated votes with no filter and multiple advanced filters:
 *    a. Filter by user_id (voter).
 *    b. Filter by post_id (votes on a post).
 *    c. Filter by comment_id (votes on a comment).
 *    d. Filter by value (+1, -1).
 *    e. Pagination edge cases (page size, over-last-page, empty result with strict filter).
 * 6. For each case, verify that only valid votes matching the filter are returned.
 * 7. Check that pagination information (current, limit, records, pages) matches expectations.
 * 8. Validate error on invalid filter parameters.
 */
export async function test_api_bbs_test_list_votes_with_filter_and_pagination_as_admin(connection: api.IConnection) {
  // Step 1: Create user roles (simulate admin/member roles)
  // For testability, we assume valid admin_role_id and member_role_id UUIDs exist or are generated
  const admin_role_id = typia.random<string & tags.Format<"uuid">>();
  const member_role_id = typia.random<string & tags.Format<"uuid">>();

  // Step 1: Create an admin account and log in as admin (admin can query the votes list)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: adminEmail,
      password: "1234_Admin!",
      bio: "Admin test account",
      role_id: admin_role_id
    }
  });
  typia.assert(adminUser);

  // Create multiple normal users
  const userInfos = await ArrayUtil.asyncRepeat(3)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const user = await api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.name(),
        email,
        password: "1234_User!",
        bio: "Regular member",
        role_id: member_role_id
      }
    });
    typia.assert(user);
    return user;
  });

  // Step 2: Create posts under various users
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const posts = await ArrayUtil.asyncMap(userInfos)(async (user) => {
    // Simulate login by user (if auth required); here assumed unnecessary for creation
    return await api.functional.bbs.posts.post(connection, {
      body: {
        category_id,
        title: RandomGenerator.paragraph()(),
        content: RandomGenerator.content()()()
      }
    });
  });
  posts.forEach(typia.assert);

  // Step 3: Add comments to every post
  const comments = await ArrayUtil.asyncMap(posts)(async (post, i) => {
    // Alternate users for authorship
    const author = userInfos[i % userInfos.length];
    const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: RandomGenerator.paragraph()()
      }
    });
    typia.assert(comment);
    return comment;
  });

  // Step 4: Votes on posts and comments, by each user
  // Each user votes +1 on all posts, -1 on all comments
  const votes: IBbsVote[] = [];
  for (const user of userInfos) {
    for (const post of posts) {
      votes.push(
        await api.functional.bbs.votes.post(connection, {
          body: {
            post_id: post.id,
            value: 1
          }
        })
      );
    }
    for (const comment of comments) {
      votes.push(
        await api.functional.bbs.votes.post(connection, {
          body: {
            comment_id: comment.id,
            value: -1
          }
        })
      );
    }
  }
  votes.forEach(typia.assert);

  // Step 5a: As admin, list votes with no filter (pagination limit set low)
  const result1 = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: 1,
      limit: 2
    }
  });
  typia.assert(result1);
  TestValidator.equals("pagination limit")(result1.pagination.limit)(2);
  // Confirm only limit number of votes per page
  TestValidator.predicate("results <= limit")(result1.data.length <= 2);

  // Step 5b: Filter by user_id
  const filterUser = userInfos[0];
  const result2 = await api.functional.bbs.votes.patch(connection, {
    body: {
      user_id: filterUser.id
    }
  });
  typia.assert(result2);
  TestValidator.predicate("all votes by user")(result2.data.every(v => v.user_id === filterUser.id));

  // Step 5c: Filter by post_id
  const filterPost = posts[1];
  const result3 = await api.functional.bbs.votes.patch(connection, {
    body: {
      post_id: filterPost.id
    }
  });
  typia.assert(result3);
  TestValidator.predicate("votes all for post")(result3.data.every(v => v.post_id === filterPost.id));

  // Step 5d: Filter by comment_id
  const filterComment = comments[0];
  const result4 = await api.functional.bbs.votes.patch(connection, {
    body: {
      comment_id: filterComment.id
    }
  });
  typia.assert(result4);
  TestValidator.predicate("votes all for comment")(result4.data.every(v => v.comment_id === filterComment.id));

  // Step 5e: Filter by value (+1 or -1)
  const result5 = await api.functional.bbs.votes.patch(connection, {
    body: {
      value: 1
    }
  });
  typia.assert(result5);
  TestValidator.predicate("all upvotes")(result5.data.every(v => v.value === 1));

  const result6 = await api.functional.bbs.votes.patch(connection, {
    body: {
      value: -1
    }
  });
  typia.assert(result6);
  TestValidator.predicate("all downvotes")(result6.data.every(v => v.value === -1));

  // Step 5f: Pagination edge cases (past last page: expect empty data)
  const pastLastPage = (result1.pagination.pages ?? 5) + 1;
  const result7 = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: pastLastPage
    }
  });
  typia.assert(result7);
  TestValidator.equals("empty on out-of-bounds page")(result7.data.length)(0);

  // Step 5g: Strict filter for zero results (random user and post)
  const result8 = await api.functional.bbs.votes.patch(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      post_id: typia.random<string & tags.Format<"uuid">>()
    }
  });
  typia.assert(result8);
  TestValidator.equals("empty for no matching filters")(result8.data.length)(0);

  // Step 6: Validate error on invalid filter parameter (e.g., page = -1)
  await TestValidator.error("invalid page param")(() =>
    api.functional.bbs.votes.patch(connection, {
      body: { page: -1 as any }
    })
  );
}

