import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsVote } from "../../../structures/IBbsVote";
import { IPageIBbsVote } from "../../../structures/IPageIBbsVote";

/**
 * Query/search all votes across posts/comments (votes table, patch for advanced
 * search).
 *
 * This operation returns a paginated and/or filtered list of votes. The 'votes'
 * table supports querying by voter, content (post or comment), vote value, and
 * timestamp. Filtering and pagination information are specified via the request
 * body. This operation is intended for use by administrators, moderators, or
 * analytics tools. Business rules enforce visibility (e.g., users see only
 * their own votes unless they have elevated permissions).
 *
 * Standard pagination, search, and sorting are provided. Errors for invalid
 * parameters or unauthorized access are handled according to platform
 * requirements.
 *
 * @param props.connection
 * @param props.body Filters, pagination, and search fields for querying vote
 *   records.
 * @path /bbs/votes
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /** Filters, pagination, and search fields for querying vote records. */
    body: IBbsVote.IRequest;
  };
  export type Body = IBbsVote.IRequest;
  export type Response = IPageIBbsVote;

  export const METADATA = {
    method: "PATCH",
    path: "/bbs/votes",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
