/**
 * Validate that listing votes through the /bbs/votes PATCH endpoint is restricted to privileged users only.
 *
 * This test ensures that non-authenticated (guest) users and regular non-privileged users are denied access
 * when attempting to list votes. The expected outcome is an error response indicating forbidden or unauthorized
 * access in each case.
 *
 * Steps:
 * 1. Attempt to call the endpoint as a guest (no bearer token in connection.headers). Confirm that access is denied.
 * 2. Attempt to call the endpoint as a regular user (non-privileged; assume a minimal connection with authentication but no special roles).
 * 3. For both scenarios, catch and validate that the resulting error matches the expected access-denied logic (error type, status code, etc.).
 */
export async function test_api_bbs_test_list_votes_unauthorized_access_denied(connection: api.IConnection) {
  // 1. Attempt as guest (no Authorization header): Should be denied
  const guestConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete guestConnection.headers.Authorization;
  await TestValidator.error("guest user is denied")(() =>
    api.functional.bbs.votes.patch(guestConnection, {
      body: {},
    }),
  );

  // 2. Attempt as regular authenticated user (non-privileged): Should be denied
  // Simulate a regular user session, assuming the framework provides a join/login function elsewhere.
  // If no user authentication or role-handling API is present, this step is not possible here and must be omitted.

  // For this context, we re-use the same connection, assuming it's not privileged.
  await TestValidator.error("non-privileged user is denied")(() =>
    api.functional.bbs.votes.patch(connection, {
      body: {},
    }),
  );
}

