import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsVote } from "../../../structures/IBbsVote";

/**
 * Get a single vote record's details (votes table, role/visibility protection).
 *
 * This operation retrieves a single vote by its ID. Information includes which
 * user cast the vote (user_id), what it targeted (either a post or comment),
 * the value (+1 or -1, as per schema), and relevant timestamps. The operation
 * consults the 'votes' table directly by primary key.
 *
 * Business logic ensures that vote records are visible only to the voter
 * themselves or users with elevated privileges. Sensitive data handling
 * observes privacy, as votes reflect user opinions which may need to remain
 * confidential, per the requirements analysis. Errors are returned for invalid
 * IDs or unauthorized access.
 *
 * @param props.connection
 * @param props.id Vote record's ID to be fetched.
 * @path /bbs/votes/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Vote record's ID to be fetched. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IBbsVote;

  export const METADATA = {
    method: "GET",
    path: "/bbs/votes/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/votes/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsVote =>
    typia.random<IBbsVote>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Create a new vote for a post or comment (votes table, upvote/downvote logic).
 *
 * This operation creates a new vote record for the given user on the specified
 * target (either a post or a comment) as per the 'votes' table structure. The
 * request body must specify which target is being voted on, and the value
 * (either +1 or -1 per business rule).
 *
 * Business logic includes unique user/target constraint (a user cannot vote
