import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validates that fetching others' votes or non-existent votes is forbidden or not found.
 *
 * This test verifies that:
 * 1. An authenticated user can create and fetch their own vote by ID.
 * 2. Attempting to fetch a non-existent vote ID returns not-found (error).
 *
 * IMPORTANT: Only authenticated context is available—SDK does not provide methods to switch users or operate unauthenticated. Therefore, user B/guest cases cannot be implemented and are commented.
 */
export async function test_api_bbs_test_get_vote_detail_unauthorized_or_not_found(connection: api.IConnection) {
  // 1. Create a vote as the current authenticated user
  const target_post_id = typia.random<string & tags.Format<"uuid">>();
  const vote = await api.functional.bbs.votes.post(connection, {
    body: { post_id: target_post_id, value: 1 } satisfies IBbsVote.ICreate
  });
  typia.assert(vote);

  // 2. Fetch the vote by its ID (should succeed for owner)
  const fetched = await api.functional.bbs.votes.getById(connection, { id: vote.id });
  typia.assert(fetched);
  TestValidator.equals("vote.id matches")(fetched.id)(vote.id);
  TestValidator.equals("vote user_id matches")(fetched.user_id)(vote.user_id);
  TestValidator.equals("vote post_id matches")(fetched.post_id)(vote.post_id);
  TestValidator.equals("vote value matches")(fetched.value)(vote.value);

  // 3. (Not implementable): As another authenticated user, try to fetch the vote (should fail with forbidden)
  //    Not possible: SDK has no auth user switching endpoints available.

  // 4. (Not implementable): As guest/non-authenticated, try to fetch the vote (should fail with unauthorized)
  //    Not possible: SDK does not expose connection/session manipulation.

  // 5. Attempt to fetch a completely random/non-existent vote ID (as authenticated user)
  await TestValidator.error("not-found error for non-existent vote")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // extremely unlikely to exist
    })
  );
}

