import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test successful creation of a vote on a post and enforcement of unique voting constraints.
 *
 * This test validates the following business logic:
 * - Only authenticated users can vote on posts
 * - Voting on a post requires that the post exists
 * - The user may vote (+1 or -1) on a post, and the response must have proper associations
 * - Unique voting: the same user cannot vote twice on the same post (should trigger error)
 *
 * Workflow:
 * 1. Register a regular user account (with a random, unique username/email and a valid role uuid)
 * 2. Authenticate as the user (account creation is assumed to lead to authentication for this scenario)
 * 3. Create a post as that user (with required fields; category_id and content are random/valid)
 * 4. Create a vote for the post (+1)
 *    - Validate association in response: user_id, post_id, value, etc.
 * 5. Attempt to vote a second time on the same post (should produce an error due to unique constraint)
 *    - Confirm that an error is thrown
 */
export async function test_api_bbs_test_create_vote_on_post_with_valid_data(connection: api.IConnection) {
  // 1. Register a regular user account
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphabets(12);
  const email = `${username.toLowerCase()}@bbs-e2e.com`;
  const password = "Secr3t!pass";
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio: RandomGenerator.paragraph()(1),
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post as that user
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Vote on the post (+1)
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("user ID on vote matches voter")(vote.user_id)(user.id);
  TestValidator.equals("post ID on vote matches post")(vote.post_id)(post.id);
  TestValidator.equals("vote value is +1")(vote.value)(1);

  // 4. Vote again on the same post (should error due to unique constraint)
  await TestValidator.error("Cannot double vote on the same post")(() =>
    api.functional.bbs.votes.post(connection, {
      body: {
        post_id: post.id,
        value: 1,
      } satisfies IBbsVote.ICreate,
    })
  );
}

