import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test that a user is prevented from creating duplicate votes on the same target (either post or comment).
 *
 * This test ensures enforcement of the unique one-vote-per-target-per-user business rule for both posts and comments.
 * It covers two paths: voting on a post and voting on a comment.
 *
 * Steps:
 * 1. Create a user (with role assignment)
 * 2. Create a post (to serve as voting target)
 * 3. (OPTIONALLY: Create a comment, if comment voting supported)
 * 4. Cast a first vote by the user on the post (should succeed)
 * 5. Attempt to cast a second vote by the same user on the same post (should fail with unique constraint error)
 * 6. (If comment voting supported: Repeat steps 4-5 for comment)
 * 7. Validate that error is thrown for duplication for both post and comment vote attempts
 */
export async function test_api_bbs_test_create_vote_duplicate_on_same_target_fails(connection: api.IConnection) {
  // 1. Create a user
  const user: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!@#",
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: RandomGenerator.paragraph()(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post
  const post: bbsPosts = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Vote on post: First vote should succeed
  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      comment_id: null,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // 4. Attempt duplicate vote on the same post: Should fail
  await TestValidator.error("duplicate post vote fails")(() =>
    api.functional.bbs.votes.post(connection, {
      body: {
        post_id: post.id,
        comment_id: null,
        value: 1,
      } satisfies IBbsVote.ICreate,
    })
  );

  // --- If/when comment voting is supported, similar logic ---
  // (Assuming comment endpoints exist and are available. Not implemented here due to lack of comment API in given materials.)
}

