import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate that unauthenticated users (guests) cannot create votes on posts.
 *
 * Business context: Only logged-in users are permitted to cast votes (upvote/downvote) on posts in the BBS. This is a critical security requirement to prevent anonymous manipulation of community discussions and reputation systems. This test ensures that vote creation fails with an authentication error if attempted by a guest (no bearer token).
 *
 * Step-by-step process:
 * 1. Create a legitimate post as a vote target by calling the /bbs/posts POST endpoint with valid data. This ensures an existing post_id for the test.
 * 2. Simulate an unauthenticated (guest) connection by clearing/removing authentication details from the connection object.
 * 3. Attempt to cast a vote for the post as a guest by calling /bbs/votes POST with the post_id and a valid value (+1 or -1).
 * 4. Assert that the vote creation request fails due to lack of authentication (access/login required error).
 */
export async function test_api_bbs_test_create_vote_unauthorized_user_fails(connection: api.IConnection) {
  // 1. Create a legitimate BBS post using a valid authenticated connection.
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Vote Security Test Post",
      content: "This post is created for voting permission test."
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 2. Simulate guest: remove authentication by cloning and clearing headers (specifically the Authorization header).
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {
      ...(connection.headers ? connection.headers : {}),
    }
  };
  delete guestConnection.headers?.Authorization;

  // 3. Attempt to create a vote on the post as a guest
  await TestValidator.error("Unauthenticated user cannot create vote")(
    () =>
      api.functional.bbs.votes.post(guestConnection, {
        body: {
          post_id: post.id,
          value: 1,
        } satisfies IBbsVote.ICreate,
      })
  );
}

