import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate that a vote's value can be updated by its owner.
 *
 * This test simulates a complete workflow in which a newly created user casts an upvote (+1) on a freshly created post,
 * and then, as the vote owner, updates their vote to a downvote (-1). This scenario ensures:
 * - Only the owner can update their vote
 * - The vote 'value' updates correctly in the vote record
 * - The update doesn't break business rules for valid values (-1, 1)
 * - (If feasible) The target aggregation/tally is also consistent (out of primary scope, as no tally endpoint)
 *
 * Workflow:
 * 1. Register a user with a unique username, email, and password. Assign a random valid role.
 * 2. Create a post as a target for voting, using a random category id and content.
 * 3. As that user, cast an upvote (+1) on the post.
 * 4. Update the vote record to change the value from +1 to -1 via /bbs/votes/{id} (PUT).
 * 5. Assert that the updated vote record reflects the new value and preserves other fields (e.g., user_id, post_id).
 */
export async function test_api_bbs_test_update_vote_value_successful_as_owner(
  connection: api.IConnection,
) {
  // 1. Register a user
  // We must assign a valid user_role_id (simulate with random uuid)
  const userInput: IBbsUsers.ICreate = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    role_id: typia.random<string & tags.Format<"uuid">>()
  };
  const user = await api.functional.bbs.users.post(connection, { body: userInput });
  typia.assert(user);

  // 2. Create a post for voting
  const postInput: bbsPosts.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(2),
    content: RandomGenerator.content()()(3)
  };
  const post = await api.functional.bbs.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 3. Cast an upvote (+1)
  const voteCreate: IBbsVote.ICreate = {
    post_id: post.id,
    value: 1
  };
  const initialVote = await api.functional.bbs.votes.post(connection, { body: voteCreate });
  typia.assert(initialVote);
  TestValidator.equals("vote user matches")(initialVote.user_id)(user.id);
  TestValidator.equals("vote post matches")(initialVote.post_id)(post.id);
  TestValidator.equals("vote value is +1")(initialVote.value)(1);

  // 4. Update the vote to -1
  const updatePayload: IBbsVote.IUpdate = { value: -1 };
  const updatedVote = await api.functional.bbs.votes.putById(connection, {
    id: initialVote.id,
    body: updatePayload,
  });
  typia.assert(updatedVote);
  TestValidator.equals("user_id unchanged")(updatedVote.user_id)(initialVote.user_id);
  TestValidator.equals("post_id unchanged")(updatedVote.post_id)(initialVote.post_id);
  TestValidator.equals("vote value updated")(updatedVote.value)(-1);
}

