import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test that only the vote owner or privileged users can update vote records.
 *
 * This test ensures that vote update rights are correctly enforced:
 * - Only the user who created the vote (the owner) or privileged users (e.g., moderators) can update a vote record.
 * - Attempts to update a vote by another regular user (who is not the owner), or as a guest (unauthenticated) must fail.
 * - Updating as a user with sufficient privilege (moderator) should succeed.
 *
 * Steps:
 * 1. Create three distinct users: one regular (as the vote owner), another regular (non-owner), and one with moderator role (privileged). Use fixed role ids to distinguish roles.
 * 2. Have the owner user create a post (which the vote will target).
 * 3. Have the owner user vote on the post (creates the vote record).
 * 4. Attempt to update the vote as:
 *    a) The owner (should succeed)
 *    b) Another regular user (should fail)
 *    c) A guest (should fail)
 *    d) The moderator (should succeed)
 * 5. Assert behaviors match permissions: success only for owner/mod, error for unauthorized/guest.
 *
 * The test covers positive (authorized) and negative (unauthorized/guest) paths.
 */
export async function test_api_bbs_test_update_vote_as_non_owner_or_unauthorized_fails(connection: api.IConnection) {
  // Setup: define role UUIDs for regular and moderator roles. In real deployment, these would be loaded from user_roles, but for test, use static randoms.
  const REGULAR_ROLE_ID = typia.random<string & tags.Format<"uuid">>();
  const MODERATOR_ROLE_ID = typia.random<string & tags.Format<"uuid">>();

  // Create users
  const owner = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: REGULAR_ROLE_ID,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(owner);

  const nonOwner = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: REGULAR_ROLE_ID,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(nonOwner);

  const moderator = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: MODERATOR_ROLE_ID,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(moderator);

  // As owner: create post
  // (Assumes connection context switches to user via session. If not, token switching code would be inserted here.)
  // For this test, we'll assume session context is managed externally and we simulate per-user session for each call.
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: "Test Post for Vote Permissions",
      content: "This post is created to test vote update permissions.",
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // As owner: create vote on post
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // -- Try updating as each identity --

  // As owner: update vote value (should succeed)
  const ownerVoteUpdate = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IBbsVote.IUpdate,
  });
  typia.assert(ownerVoteUpdate);
  TestValidator.equals("owner can update their own vote")(ownerVoteUpdate.value)(-1);

  // As non-owner, try update (should fail)
  await TestValidator.error("non-owner should not be able to update vote")(async () => {
    await api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: 1 } satisfies IBbsVote.IUpdate,
    });
  });

  // As guest (no user context), try update (should fail)
  await TestValidator.error("guest (unauthenticated) should not be able to update vote")(async () => {
    await api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: 1 } satisfies IBbsVote.IUpdate,
    });
  });

  // As moderator, try update (should succeed)
  const moderatorVoteUpdate = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: { value: 1 } satisfies IBbsVote.IUpdate,
  });
  typia.assert(moderatorVoteUpdate);
  TestValidator.equals("moderator can update vote")(moderatorVoteUpdate.value)(1);
}

