import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsVote } from "../../../structures/IBbsVote";

/**
 * Update an existing vote (votes table, upvote/downvote change).
 *
 * This operation updates an existing vote, which is identified by its unique
 * ID. Only the owner (voter) of the vote or privileged roles (moderator/admin)
 * may perform updates. Fields that can be changed include 'value' (e.g., switch
 * an upvote to a downvote) and potentially metadata (e.g., audit fields). The
 * business rules from the schema and requirements analysis govern what can be
 * changed and by whom.
 *
 * Changes are reflected in the database and in derived content tallies. Errors
 * are returned if update rules are violated (e.g., changing someone else's
 * vote, updating a vote that doesn't exist, improper value assignment). On
 * success, returns updated vote resource.
 *
 * @param props.connection
 * @param props.id Vote record's ID to update.
 * @param props.body Updated vote fields (e.g., value).
 * @path /bbs/votes/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function putById(
  connection: IConnection,
  props: putById.Props,
): Promise<putById.Response> {
  return !!connection.simulate
    ? putById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...putById.METADATA,
          path: putById.path(props),
          status: null,
        },
        props.body,
      );
}
export namespace putById {
  export type Props = {
    /** Vote record's ID to update. */
    id: string & tags.Format<"uuid">;

    /** Updated vote fields (e.g., value). */
    body: IBbsVote.IUpdate;
  };
  export type Body = IBbsVote.IUpdate;
  export type Response = IBbsVote;

  export const METADATA = {
    method: "PUT",
    path: "/bbs/votes/:id",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Omit<Props, "body">) =>
    `/bbs/votes/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsVote =>
    typia.random<IBbsVote>(g);
  export const simulate = (
    connection: IConnection,
    props: putById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: putById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

