import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate the behavior of updating a vote with a nonexistent (invalid) ID.
 *
 * This test attempts to update a vote record by providing a UUID that does not correspond
 * to any existing record in the database. The test ensures that the API responds with the
 * correct error, specifically a not-found response (typically HTTP 404), rather than allowing
 * the operation or returning a different error.
 *
 * Step-by-step process:
 * 1. Generate a random UUID that does not correspond to any valid vote record (simulate a nonexistent ID).
 * 2. Attempt to update the vote resource using the API endpoint, providing the invalid ID and a plausible update payload.
 * 3. Expect the API call to fail with a not-found error (HTTP 404), and verify that the correct error handling occurs.
 *
 * This test verifies robust error handling and proper business logic enforcement for the case of updating a vote with an invalid/nonexistent ID.
 */
export async function test_api_bbs_test_update_vote_with_invalid_id_returns_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID to simulate a nonexistent vote record
  const invalidVoteId = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare plausible update information (valid value field)
  const updatePayload = { value: 1 } satisfies IBbsVote.IUpdate;

  // 3. Attempt to update and expect a not-found error
  await TestValidator.error("updating nonexistent vote fails with 404")(
    async () => {
      await api.functional.bbs.votes.putById(connection, {
        id: invalidVoteId,
        body: updatePayload,
      });
    },
  );
}

