import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validates that both the vote owner and an administrator can delete a vote, allowing re-casting on the same target.
 * 
 * Business logic: Once a user votes (on a post), only the vote owner or an admin can delete that vote. After deletion,
 * the user is free to cast a new vote for the same post. The test ensures permission logic, the correct erasure, and that all
 * business constraints (like one-vote-per-target-per-user) are maintained/released as expected.
 * 
 * Process:
 * 1. Register normal user (vote owner) and admin user, each with appropriate roles.
 * 2. Register a category as prerequisite (if needed for posts), or select a plausible UUID for category_id (since category system is out of scope here).
 * 3. Owner user creates a post (Post A); Admin user creates a post (Post B) to ensure role separation for the test.
 * 4. Owner user casts a vote on Post A. Confirm vote can be created only once.
 * 5. Owner user deletes their own vote. Confirm deletion succeeds (no content returned, no error).
 * 6. Owner user re-casts vote on Post A after deletion. Confirm succeeds, enforcing business rule.
 * 7. Admin user casts a vote on Post B. Confirm success.
 * 8. Now, admin deletes their own vote on Post B (to cover admin-as-owner).
 * 9. Owner user casts a vote on Post B as well, and admin deletes owner’s vote as an administrator.
 * 10. Confirm at each step that only one vote exists per user/target and appropriate users have permission for erasure. For tally confirmation and querying, steps are limited to permitted operations (since no listing or tally API is exposed).
 */
export async function test_api_bbs_test_delete_vote_successful_by_owner_and_admin(connection: api.IConnection) {
  // 1. Register user role UUIDs for member and admin. For this test, use random UUIDs (real system would fetch actual roles)
  const memberRoleId = typia.random<string & tags.Format<'uuid'>>();
  const adminRoleId = typia.random<string & tags.Format<'uuid'>>();

  // 2. Create normal user (vote owner) and admin user
  const ownerEmail = typia.random<string & tags.Format<'email'>>();
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const ownerUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: ownerEmail,
      password: 'Pwd1$' + RandomGenerator.alphaNumeric(5),
      role_id: memberRoleId,
      bio: 'Vote owner',
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(ownerUser);

  const adminUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: adminEmail,
      password: 'Pwd1$' + RandomGenerator.alphaNumeric(6),
      role_id: adminRoleId,
      bio: 'Admin user',
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(adminUser);

  // 3. Create category UUID for posts, then create two posts (A, B)
  const categoryId = typia.random<string & tags.Format<'uuid'>>();

  // Switch to owner session (assume connection reflects user context by output; no explicit login API here)
  const ownerPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: 'Test post by owner',
      content: 'Test content for post by vote owner',
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(ownerPost);

  // Switch to admin session
  const adminPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: 'Test post by admin',
      content: 'Test content for post by admin',
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(adminPost);

  // 4. Owner user casts vote on Post A, confirm creation and one-per-user
  const voteA = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: ownerPost.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(voteA);
  TestValidator.equals('vote owner id == owner user')(voteA.user_id)(ownerUser.id);
  TestValidator.equals('vote post id == PostA')(voteA.post_id)(ownerPost.id);

  // 5. Owner deletes their own vote
  await api.functional.bbs.votes.eraseById(connection, { id: voteA.id });
  // Try voting again (should succeed since vote is deleted)
  const voteA2 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: ownerPost.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(voteA2);
  TestValidator.equals('vote owner id == owner user')(voteA2.user_id)(ownerUser.id);

  // 7. Admin casts vote on Post B
  const voteB_admin = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: adminPost.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(voteB_admin);
  TestValidator.equals('admin user votes Post B')(voteB_admin.user_id)(adminUser.id);

  // 8. Admin deletes own vote
  await api.functional.bbs.votes.eraseById(connection, { id: voteB_admin.id });

  // 9. Owner user votes Post B, admin deletes owner's vote on Post B
  const voteB_owner = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: adminPost.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(voteB_owner);
  TestValidator.equals('owner user votes Post B')(voteB_owner.user_id)(ownerUser.id);

  await api.functional.bbs.votes.eraseById(connection, { id: voteB_owner.id });

  // 10. After deletion, owner can re-cast vote on Post B
  const voteB_owner2 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: adminPost.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(voteB_owner2);
  TestValidator.equals('owner user votes Post B again')(voteB_owner2.user_id)(ownerUser.id);
}

