import { tags } from "typia";

/**
 * A single vote record (post or comment vote).
 *
 * Defines the core information about a user-provided upvote/downvote for either
 * a post or comment. Per schema, only one of post_id or comment_id is populated
 * for each record. Business rules for voting integrity apply.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IBbsVote = {
  /** Unique identifier for the vote record. Maps to votes.id in Prisma schema. */
  id: string & tags.Format<"uuid">;

  /**
   * User (voter) UUID that cast this vote. From votes.user_id. Used for
   * auditing and per-user history.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * UUID of the post being voted on, if applicable. From votes.post_id.
   * Mutually exclusive with comment_id per schema.
   */
  post_id?: (string & tags.Format<"uuid">) | null;

  /**
   * UUID of the comment being voted on, if applicable. From votes.comment_id.
   * Mutually exclusive with post_id.
   */
  comment_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Vote value: +1 for upvote, -1 for downvote. Enforced by DB check and
   * business rules. From votes.value.
   */
  value: -1 | 1;

  /**
   * Timestamp when the vote was made. From votes.created_at. Used for
   * auditing, reporting, and analytics.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IBbsVote {
  /**
   * Object for creating a vote on a post or comment.
   *
   * Specifies the target entity (post_id or comment_id) and the value
   * (+1/-1). Enforces one-vote-per-target-per-user as described in
   * requirements and Prisma schema.
   */
  export type ICreate = {
    /**
     * ID of the post to be voted on. Set this or comment_id, but not both.
     * Enforced by business logic and unique constraint (see
     * votes.post_id).
     */
    post_id?: (string & tags.Format<"uuid">) | null;

    /**
     * ID of the comment to be voted on. Set this or post_id, but not both.
     * Only one target can be set. From votes.comment_id.
     */
    comment_id?: (string & tags.Format<"uuid">) | null;

    /**
     * Required. Vote value: +1 (upvote) or -1 (downvote). Enforced by
     * schema and business rules.
     */
    value: -1 | 1;
  };
}

