/**
 * Validate that a non-owner/non-privileged user is forbidden from deleting another user's vote.
 *
 * Business Context:
 * - Only the vote owner or privileged users (moderator/admin) can delete a vote record.
 * - Regular users should be denied permission when attempting to delete votes they do not own.
 *
 * Test Workflow:
 * 1. Create two distinct user accounts (userA: the vote owner; userB: attacker)
 * 2. UserA creates a post (targetPost) for voting
 * 3. UserA casts a vote (voteA) on the post
 * 4. UserB logs in and attempts to delete voteA (should be denied by system)
 * 5. Validate that permission is denied (expected: HttpError with forbidden status)
 * 6. Confirm that voteA remains present (not deleted)
 */
export async function test_api_bbs_test_delete_vote_as_non_owner_fails(
  connection: api.IConnection,
) {
  // 1. Create userRoleId (member)
  const userRoleMemberId = typia.random<string & tags.Format<"uuid">>();

  // 2. Register UserA (vote owner)
  const userACredentials = {
    username: RandomGenerator.alphaNumeric(8),
    email: RandomGenerator.alphaNumeric(8) + "@mail.com",
    password: "TestPass1234!",
    bio: RandomGenerator.paragraph()(),
    role_id: userRoleMemberId,
  } satisfies IBbsUsers.ICreate;
  const userA = await api.functional.bbs.users.post(connection, { body: userACredentials });
  typia.assert(userA);
  const userAId = userA.id;

  // 3. Register UserB (attacker)
  const userBCredentials = {
    username: RandomGenerator.alphaNumeric(8),
    email: RandomGenerator.alphaNumeric(8) + "@mail.com",
    password: "TestPass1234!",
    bio: RandomGenerator.paragraph()(),
    role_id: userRoleMemberId,
  } satisfies IBbsUsers.ICreate;
  const userB = await api.functional.bbs.users.post(connection, { body: userBCredentials });
  typia.assert(userB);

  // 4. Log in as UserA (assume implementation: manipulation of connection.headers to impersonate userA)
  //    For the purposes of this test, assume connection can be impersonated for each user account

  // 5. UserA creates a post
  const postPayload = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.paragraph()(),
  } satisfies bbsPosts.ICreate;
  const post = await api.functional.bbs.posts.post(connection, { body: postPayload });
  typia.assert(post);
  const postId = post.id;

  // 6. UserA votes on the post
  const votePayload = { post_id: postId, value: 1 } satisfies IBbsVote.ICreate;
  const vote = await api.functional.bbs.votes.post(connection, { body: votePayload });
  typia.assert(vote);
  const voteId = vote.id;

  // 7. Switch session to UserB (non-owner)
  //    Again, assume we can update connection.headers to represent UserB's session

  // 8. UserB attempts to delete the vote owned by UserA
  await TestValidator.error("Non-owner cannot delete another user's vote")(
    async () =>
      await api.functional.bbs.votes.eraseById(connection, { id: voteId }),
  );

  // 9. (Optional) Confirm the vote is still present (not deleted)
  //    As we do not have a GET for individual votes in SDK, this confirmation may be omitted.
}

