/**
 * Register a new user account (users table).
 *
 * This operation allows either new users to self-register (signup) or
 * administrative users to create new user accounts. Inputs include: username,
 * email, password (plain, which will be hashed), role, and optional biography.
 * Usernames and emails must be unique system-wide as enforced by the DB. Role
 * assignment references the user_roles table (role name or ID). On successful
 * creation, returns full non-sensitive account data (never returns password
 * hash or plain password). Validation includes strong password policies,
 * correctly-formed emails, unique username check, assignment of allowed roles,
 * and correct audit metadata. Security policies ensure only authorized clients
 * can create moderator/administrator accounts. Relationship: users references
 * user_roles via user_role_id (UUID). The operation complements authentication
 * endpoints and supports user onboarding workflows. Error handling includes
 * duplicate entries, invalid roles, and input format errors.
 *
 * @param props.connection
 * @param props.body User account registration information, including username,
 *   email, password, role, and optional bio.
 * @path /bbs/users
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * User account registration information, including username, email,
     * password, role, and optional bio.
     */
    body: IBbsUsers.ICreate;
  };
  export type Body = IBbsUsers.ICreate;
  export type Response = IBbsUsers;

  export const METADATA = {
    method: "POST",
    path: "/bbs/users",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/bbs/users";
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsUsers =>
    typia.random<IBbsUsers>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

