import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate failed deletion attempts of a vote with invalid or already-deleted IDs.
 *
 * This test ensures the system returns proper errors when trying to delete a vote using:
 *  - a non-existent (random/invalid) vote ID
 *  - a previously deleted vote ID (attempting double delete)
 *
 * Steps:
 * 1. Register a new user (dependency, as deletion requires an authenticated context)
 * 2. Attempt to delete a totally invalid/random vote ID, expect error (e.g., not found)
 * 3. (Simulated—since we cannot create a vote via available APIs):
 *    a. Delete a random vote ID (system will return not found/error)
 *    b. Attempt to delete the same ID again (system should return the same or conflict error)
 *
 * Note: API does not provide endpoint to create a vote, so we only test invalid scenarios.
 */
export async function test_api_bbs_test_delete_vote_with_invalid_id_fails(
  connection: api.IConnection,
) {
  // 1. Register a new user for context (may not affect deletion, but follows dependency)
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: `${RandomGenerator.alphabets(8)}@test.com`,
      password: "Test!1234",
      bio: null,
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to delete a non-existent/random vote ID, expect error
  await TestValidator.error("deleting nonexistent vote should fail")(async () => {
    await api.functional.bbs.votes.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 3. Simulate double delete on same random ID, expect repeated failure
  const fakeVoteId = typia.random<string & tags.Format<"uuid">>();
  // First delete attempt (should error)
  await TestValidator.error("deleting invalid vote first attempt fails")(async () => {
    await api.functional.bbs.votes.eraseById(connection, {
      id: fakeVoteId
    });
  });
  // Second delete attempt on same ID (should error in same or similar fashion)
  await TestValidator.error("deleting invalid vote second attempt fails")(async () => {
    await api.functional.bbs.votes.eraseById(connection, {
      id: fakeVoteId
    });
  });
}

