import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IPageBbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing posts with search, filter, sort, and pagination parameters.
 *
 * This test simulates a real-world scenario where a user wants to view discussion threads in a specific category, sorted by creation date and paginated. The process involves:
 *   1. Creating a user account for authentication and post creation.
 *   2. Registering multiple categories for posts to be assigned to.
 *   3. Having the user create several posts, distributed across those categories.
 *   4. Performing a filtered post listing request: Only posts from a selected category, sorted by newest (created_at desc), and paginated (limit, page).
 *   5. Verifying the response contains only posts matching the filter (category), that ordering and page size constraints are adhered to, and that pagination metadata is accurate (total records, current page, pages, etc.).
 *
 * Edge cases include verifying:
 *   - Page limits are enforced (response data length ≤ limit).
 *   - Posts from other categories do not appear.
 *   - Sort order is correct (descending by creation date).
 *   - Pagination metadata matches dataset.
 */
export async function test_api_bbs_test_list_posts_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create a user role (assuming the role must exist)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  // 2. Create a user with the role
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass123!",
      role_id: userRoleId,
      bio: RandomGenerator.paragraph()(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 3. Create categories
  const categories = await ArrayUtil.asyncRepeat(3)(async () => {
    const name = RandomGenerator.alphaNumeric(6);
    const category = await api.functional.bbs.categories.post(connection, {
      body: { name, description: RandomGenerator.paragraph()() } satisfies bbsCategories.ICreate,
    });
    typia.assert(category);
    return category;
  });

  // 4. Create posts distributed across categories
  const numPosts = 7;
  const posts: bbsPosts[] = [];
  for (let i = 0; i < numPosts; ++i) {
    const cat = RandomGenerator.pick(categories);
    const post = await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: cat.id,
        title: RandomGenerator.paragraph()(),
        content: RandomGenerator.content()()(),
      } satisfies bbsPosts.ICreate,
    });
    typia.assert(post);
    posts.push(post);
  }

  // 5. Choose a target category to filter
  const targetCategory = RandomGenerator.pick(categories);
  const filteredPosts = posts
    .filter((post) => post.category_id === targetCategory.id)
    .sort((a, b) => b.created_at.localeCompare(a.created_at));

  // 6. List posts filtered by category, sorted, paginated
  const pageLimit = 2;
  const pageNum = 1;
  const listResult = await api.functional.bbs.posts.patch(connection, {
    body: {
      category_id: targetCategory.id,
      sort_by: "created_at",
      order: "desc",
      limit: pageLimit,
      page: pageNum,
    } satisfies bbsPosts.IRequest,
  });
  typia.assert(listResult);

  // 7. Validate the response contains only posts from the target category
  TestValidator.predicate("filtered posts all match category")(
    listResult.data.every((p) => p.category_id === targetCategory.id)
  );
  // 8. Validate data length respects limit
  TestValidator.predicate("page size limit respected")(
    listResult.data.length <= pageLimit
  );
  // 9. Validate the posts are sorted by created_at descending
  TestValidator.predicate("descending order by created_at")(
    listResult.data.every((p, idx, arr) =>
      idx === 0 ? true : p.created_at <= arr[idx - 1].created_at
    )
  );
  // 10. Validate pagination metadata
  TestValidator.equals("pagination current page")(
    listResult.pagination.current
  )(pageNum);
  TestValidator.equals("pagination limit")(
    listResult.pagination.limit
  )(pageLimit);
  TestValidator.equals("pagination records (should match filtered dataset)")(
    listResult.pagination.records
  )(filteredPosts.length);
}

