  await TestValidator.error("negative limit is rejected")(async () => {
    await api.functional.bbs.posts.patch(connection, {
      body: { limit: -5 },
    });
  });

  // 2.2. Attempt with zero page number (if business logic forbids)
  await TestValidator.error("zero page is rejected")(async () => {
    await api.functional.bbs.posts.patch(connection, {
      body: { page: 0 },
    });
  });

  // 2.3. Attempt with negative page number
  await TestValidator.error("negative page is rejected")(async () => {
    await api.functional.bbs.posts.patch(connection, {
      body: { page: -2 },
    });
  });

  // 2.4. Attempt with non-existent but syntactically valid category_id
