import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate successful retrieval of a post's details by its ID.
 *
 * This test ensures that after creating a user (author), creating a category, and then creating a post using both, the system correctly returns all mandatory and relevant post fields when fetching by ID. It verifies the round-trip data integrity and absence of null/missing fields for essential data.
 *
 * Process:
 * 1. Create a user account to act as the post's author
 * 2. Create a category to assign to the post
 * 3. Create a post using that user and category
 * 4. Retrieve that post by its ID
 * 5. Validate that all necessary fields are correct and not missing/null
 */
export async function test_api_bbs_test_get_post_by_id_success(connection: api.IConnection) {
  // 1. Create a user account (author)
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const userCreate = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    role_id: roleId,
    bio: RandomGenerator.paragraph()(),
  } satisfies IBbsUsers.ICreate;
  const user = await api.functional.bbs.users.post(connection, { body: userCreate });
  typia.assert(user);

  // 2. Create a category
  const categoryCreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  } satisfies bbsCategories.ICreate;
  const category = await api.functional.bbs.categories.post(connection, { body: categoryCreate });
  typia.assert(category);

  // 3. Create a post using the user and category
  const postCreate = {
    category_id: category.id,
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.content()()(),
  } satisfies bbsPosts.ICreate;
  const post = await api.functional.bbs.posts.post(connection, { body: postCreate });
  typia.assert(post);

  // 4. Retrieve the post by its ID
  const reloaded = await api.functional.bbs.posts.getById(connection, { id: post.id });
  typia.assert(reloaded);

  // 5. Validate that all necessary fields match and are not missing/null
  TestValidator.equals("post id should match")(reloaded.id)(post.id);
  TestValidator.equals("category id should match")(reloaded.category_id)(category.id);
  TestValidator.equals("title should match")(reloaded.title)(postCreate.title);
  TestValidator.equals("content should match")(reloaded.content)(postCreate.content);
  TestValidator.predicate("user_id present and in uuid format")(!!reloaded.user_id && reloaded.user_id.length > 0);
  TestValidator.predicate("created_at is a string")(typeof reloaded.created_at === "string");
  TestValidator.predicate("updated_at is a string")(typeof reloaded.updated_at === "string");
  TestValidator.predicate("deleted_at is undefined or null or valid date string")(
    reloaded.deleted_at === undefined || reloaded.deleted_at === null || typeof reloaded.deleted_at === "string"
  );
  // Should not have missing/undefined values for required fields
  ["id","user_id","category_id","title","content","created_at","updated_at"].forEach((k) => {
    if (reloaded[k as keyof typeof reloaded] === undefined || reloaded[k as keyof typeof reloaded] === null)
      throw new Error(`Required field ${k} is missing/null in reloaded post.`);
  });
}

