import { tags } from "typia";

/**
 * Represents a discussion post (thread) on the platform, matching the posts
 * entity from the requirements analysis and the posts table in the Prisma
 * schema.
 *
 * Provides all information about the post, including subject/title, content,
 * author ID, category, timestamps, and deletion flag for moderation.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type bbsPosts = {
  /**
   * Unique identifier of the post. The `id` field in the posts model.
   *
   * Used for referencing the post in API calls or links.
   */
  id: string & tags.Format<"uuid">;

  /**
   * UUID of the user (author) who created this post, corresponding to
   * `user_id` in the posts table.
   *
   * Provides author traceability and links to user profiles.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * UUID of the category under which the post was published, referencing
   * `category_id` in the posts table.
   *
   * Supports topic-based navigation and organization.
   */
  category_id: string & tags.Format<"uuid">;

  /**
   * The post's headline/title. Implements the required `title` property in
   * the posts schema.
   *
   * Prominently displayed in thread lists and views.
   */
  title: string;

  /**
   * Main content/body of the post, from the `content` field in the posts
   * table.
   *
   * Includes long-form text, opinion, or analysis. Critical for community
   * discussion.
   */
  content: string;

  /**
   * The timestamp when the post was created, matching `created_at` in the
   * database.
   *
   * Displayed in lists, used for freshness ordering, and necessary for
   * audits.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Last modification timestamp, from `updated_at` in the posts record.
   *
   * Enables edit history tracking and evidence of moderation or typo
   * corrections.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * If present, this timestamp indicates when the post was soft-deleted (not
   * physically removed), in line with moderation and audit business rules.
   *
   * Null if the post is currently visible.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};

