import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { bbsCategories } from "../../../structures/bbsCategories";

/**
 * Create a new category (BBS: categories table).
 *
 * This API allows an administrator to create a new discussion category in the
 * BBS platform. By supplying necessary information such as category name and
 * description, the system adds a new record to the 'categories' table.
 * Administrators should ensure names are unique to avoid conflicts with
 * existing categories.
 *
 * Access to this API is restricted to authenticated administrators, as only
 * they may modify the set of available discussion categories. Upon successful
 * creation, a new category entry is visible and available for post assignment
 * by all users, supporting better board organization.
 *
 * If the submitted category name already exists, the API will return an error
 * indicating the name must be unique. Validation rules also require non-empty
 * strings for both name and description fields.
 *
 * Related operations include listing categories, updating (PUT), and deleting
 * (DELETE) existing categories. This endpoint is essential for maintaining the
 * topical structure of the BBS, making it easier for users to navigate and
 * participate in relevant discussions.
 *
 * @param props.connection
 * @param props.body Information about the new category to create, including
 *   name and description.
 * @path /bbs/categories
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function post(
  connection: IConnection,
  props: post.Props,
): Promise<post.Response> {
  return !!connection.simulate
    ? post.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...post.METADATA,
          path: post.path(),
          status: null,
        },
        props.body,
      );
}
export namespace post {
  export type Props = {
    /**
     * Information about the new category to create, including name and
     * description.
     */
    body: bbsCategories.ICreate;
  };
  export type Body = bbsCategories.ICreate;
  export type Response = bbsCategories;

  export const METADATA = {
    method: "POST",
    path: "/bbs/categories",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/bbs/categories";
  export const random = (g?: Partial<typia.IRandomGenerator>): bbsCategories =>
    typia.random<bbsCategories>(g);
  export const simulate = (
    connection: IConnection,
    props: post.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: post.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

