import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate successful creation of a new post with valid parameters.
 *
 * This test covers the end-to-end business workflow of posting on the BBS platform:
 * - Ensures user and category prerequisites exist.
 * - Posts valid content to specified category as that user, following all creation rules.
 * - Confirms that post fields reflect author, category, and post metadata.
 * - (Note: As only post, user, and category creation functions are provided, post list/detail validation is marked for extension.)
 *
 * Steps:
 * 1. Register a user account (using unique/random username/email and referencing a role).
 * 2. Create a category (using unique/random name/description).
 * 3. Create a new post with the valid title/content under that category as the registered user.
 * 4. Validate that the returned post has expected user/category IDs, non-empty title/content/metadata.
 */
export async function test_api_bbs_test_create_post_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a user who will create the post
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category under which the post will be submitted
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a new post (as this user) with valid title, content, and category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Validate the returned post
  TestValidator.equals("author id matches")(post.user_id)(user.id);
  TestValidator.equals("category id matches")(post.category_id)(category.id);
  TestValidator.predicate("post id should be a non-empty uuid")(typeof post.id === "string" && post.id.length > 0);
  TestValidator.predicate("title non-empty")(!!post.title && post.title.length > 0);
  TestValidator.predicate("content non-empty")(!!post.content && post.content.length > 0);
  TestValidator.predicate("created_at non-empty")(!!post.created_at && post.created_at.length > 0);
  TestValidator.predicate("updated_at non-empty")(!!post.updated_at && post.updated_at.length > 0);

  // Note: List/detail API not provided, so cannot further check visibility. Extend when available.
}

