import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that post creation fails when using missing or invalid input fields.
 *
 * Test that the API rejects new posts creation when required fields are missing
 * or when data does not meet the required format or content. Ensure that all invalid
 * submissions lead to validation errors and that no post is actually created in these situations.
 *
 * Workflow:
 * 1. Register a valid user (for authentication context).
 * 2. Attempt to create a post without a title (missing required field).
 * 3. Attempt to create a post with an empty content (missing required field).
 * 4. Attempt to create a post with an invalid/non-existent category_id (should not exist in DB or is malformed).
 * 5. Attempt to create a post with clearly invalid types (e.g., wrong data type for title or category_id).
 * 6. Ensure each scenario fails with a validation/business logic error and verify that no post is created by these submissions.
 */
export async function test_api_bbs_test_create_post_with_missing_or_invalid_data(connection: api.IConnection) {
  // 1. Register a valid user for authentication context
  const userData: IBbsUsers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password!1234",
    role_id: typia.random<string & tags.Format<"uuid">>(),
    bio: RandomGenerator.paragraph()(32),
  };
  const user = await api.functional.bbs.users.post(connection, { body: userData });
  typia.assert(user);

  // 2. Attempt to create a post without title (should fail)
  await TestValidator.error("post creation fails without title")(async () => {
    await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        // title is missing
        content: RandomGenerator.content()()(),
      } as any, // Intentionally causing runtime validation error
    });
  });

  // 3. Post with empty content (should fail)
  await TestValidator.error("post creation fails with empty content")(async () => {
    await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.alphaNumeric(10),
        content: "",
      },
    });
  });

  // 4. Post with non-existent or malformed category_id (should fail)
  await TestValidator.error("post creation fails with invalid category_id")(async () => {
    await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: "not-a-uuid",
        title: RandomGenerator.alphaNumeric(10),
        content: RandomGenerator.content()()(),
      },
    });
  });

  // 5. Post with wrong data types (should fail)
  await TestValidator.error("post creation fails with non-string title")(async () => {
    await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        // @ts-expect-error
        title: 12345,
        content: RandomGenerator.content()()(),
      } as any,
    });
  });

  await TestValidator.error("post creation fails with non-string category_id")(async () => {
    await api.functional.bbs.posts.post(connection, {
      body: {
        // @ts-expect-error
        category_id: 54321,
        title: RandomGenerator.alphaNumeric(8),
        content: RandomGenerator.content()()(),
      } as any,
    });
  });
}

