import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test updating an existing post by its author with valid data.
 *
 * This test covers the workflow for a user updating a post they previously created, modifying the title, content, and category to new valid values. It starts with all dependencies:
 * 1. Creating a user (the post author)
 * 2. Creating two categories: initial and target (to validate category change)
 * 3. Creating a post under the initial category, as the created user
 *
 * Steps:
 * 1. Register a user with a random username, email, password, and member role
 * 2. Create an initial and a target category
 * 3. Create a post authored by the user in the initial category
 * 4. Update the post's title, content, and category_id (assign to the target category) with new non-empty valid values
 * 5. Validate that the updated post reflects all the changes and that timestamps (`updated_at`) are modified (is after previous `updated_at`); ensure constraints are enforced (non-empty fields and valid category)
 */
export async function test_api_bbs_test_update_post_with_valid_data_by_author(connection: api.IConnection) {
  // 1. Register a user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create initial and target categories
  const initialCategory = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.content()()(),
    },
  });
  typia.assert(initialCategory);

  const targetCategory = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.content()()(),
    },
  });
  typia.assert(targetCategory);

  // 3. Create the post under the initial category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: initialCategory.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Update the post (as author) to use new valid title, content, and target category
  const updatedTitle = RandomGenerator.paragraph()();
  const updatedContent = RandomGenerator.content()()();
  const updateRes = await api.functional.bbs.posts.putById(connection, {
    id: post.id,
    body: {
      category_id: targetCategory.id,
      title: updatedTitle,
      content: updatedContent,
    },
  });
  typia.assert(updateRes);

  // 5. Validate: fields, category, timestamps, and constraints
  TestValidator.equals("title updated")(updateRes.title)(updatedTitle);
  TestValidator.equals("content updated")(updateRes.content)(updatedContent);
  TestValidator.equals("category updated")(updateRes.category_id)(targetCategory.id);
  TestValidator.notEquals("updated_at should change after edit")(updateRes.updated_at)(post.updated_at);
  TestValidator.predicate("title non-empty")(updateRes.title.length > 0);
  TestValidator.predicate("content non-empty")(updateRes.content.length > 0);
  TestValidator.equals("user_id should not change")(updateRes.user_id)(post.user_id);
}

