import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that updating a post with invalid data results in proper failure responses and no unintended data changes.
 *
 * This test ensures that attempts to update a BBS post with various invalid payloads (such as a non-existent category ID, duplicate title, empty title, or invalid/forbidden content) are correctly rejected by the API. It further asserts that validation errors are clearly reported and that the original post data remains unchanged after failed update attempts.
 *
 * Steps:
 * 1. Create a user for authentication and authoring the post.
 * 2. Create a valid category (for use in valid/invalid assignment cases).
 * 3. Create a post with valid data as the "target" for attempted invalid updates (collect its original state for later comparison).
 * 4. Attempt to update the post with a non-existent category_id (random UUID), and assert that:
 *    - The update fails with a validation error (e.g., category not found).
 *    - The post content is unchanged.
 * 5. Attempt to update with an empty title, and assert rejection and no change.
 * 6. Attempt to update with a duplicate title (create another post first to simulate this), and assert rejection and no change.
 * 7. Attempt to update with forbidden content (simulate by inserting a known forbidden phrase if any business rules exist), assert rejection and no change.
 * 8. For each test, where update is rejected, validate that the error is actionable/clear and that reloading the post returns the original data from the setup step.
 */
export async function test_api_bbs_test_update_post_with_invalid_data(connection: api.IConnection) {
  // 1. Create a user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "ValidP@ssw0rd1234",
      role_id: userRoleId,
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a valid category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create the initial post
  const originalPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphaNumeric(12),
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(originalPost);

  // 3b. Create a second post for "duplicate title" test
  const duplicateTitle = RandomGenerator.alphaNumeric(12);
  const otherPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: duplicateTitle,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(otherPost);

  // Helper to reload original post after failed update (to verify no changes)
  async function fetchCurrentPost() {
    // There is no explicit "GET /bbs/posts/:id" API provided, so we must skip reloading, and only trust local state
    return originalPost;
  }

  // 4. Non-existent category_id
  await TestValidator.error("Non-existent category_id should fail")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: originalPost.id,
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(), // likely non-existent
        title: originalPost.title,
        content: originalPost.content,
      },
    }),
  );
  TestValidator.equals("Post remains unchanged")(await fetchCurrentPost())(originalPost);

  // 5. Empty title
  await TestValidator.error("Empty title should fail")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: originalPost.id,
      body: {
        category_id: category.id,
        title: "",
        content: originalPost.content,
      },
    }),
  );
  TestValidator.equals("Post remains unchanged")(await fetchCurrentPost())(originalPost);

  // 6. Duplicate title
  await TestValidator.error("Duplicate title should fail")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: originalPost.id,
      body: {
        category_id: category.id,
        title: duplicateTitle,
        content: originalPost.content,
      },
    }),
  );
  TestValidator.equals("Post remains unchanged")(await fetchCurrentPost())(originalPost);

  // 7. Forbidden content (simulate forbidden with e.g. 'forbidden_word')
  await TestValidator.error("Forbidden content should fail")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: originalPost.id,
      body: {
        category_id: category.id,
        title: originalPost.title,
        content: "forbidden_word_in_content",
      },
    }),
  );
  TestValidator.equals("Post remains unchanged")(await fetchCurrentPost())(originalPost);
}

