import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * 인증되지 않은 일반 유저가 자신이 작성하지 않은 게시글을 수정하려 할 때 권한 거부가 발생함을 검증합니다.
 *
 * 1. 역할(권한)이 다른 일반 사용자(공격자)와 게시글 저자(정상 사용자) 계정 두 개를 생성합니다.
 * 2. 카테고리 생성 (게시글이 속할 카테고리용)
 * 3. 저자 계정으로 로그인하여 게시글을 게시합니다.
 * 4. 공격자 계정으로 로그인하여 해당 게시글을 임의의 내용으로 수정 시도합니다.
 * 5. 권한 없음(403/401 등) 에러가 발생하고, 게시글 원본 내용은 변경되지 않았음을 검증합니다.
 */
export async function test_api_bbs_test_update_post_by_non_author_or_non_privileged_user(
  connection: api.IConnection,
) {
  // 1. (가) 게시글 저자 역할의 유저 및 (나) 비저자 역할의 일반 유저(공격자) 각각 생성
  // (1-a) 관리 권한이나 특권 없는 일반 회원 역할 임의 생성
  const simpleRoleId: string = typia.random<string & tags.Format<"uuid">>();
  // (1-b) 저자 (author)
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorUsername = RandomGenerator.alphabets(10);
  const authorPassword = RandomGenerator.alphaNumeric(12);
  const author = await api.functional.bbs.users.post(connection, {
    body: {
      username: authorUsername,
      email: authorEmail,
      password: authorPassword,
      role_id: simpleRoleId,
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(author);
  // (1-c) 공격자 (attacker, 이 게시글을 수정 시도)
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const attackerUsername = RandomGenerator.alphabets(10);
  const attackerPassword = RandomGenerator.alphaNumeric(12);
  const attacker = await api.functional.bbs.users.post(connection, {
    body: {
      username: attackerUsername,
      email: attackerEmail,
      password: attackerPassword,
      role_id: simpleRoleId, // 동일한 일반 회원 역할 -> 특권 없음
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(attacker);

  // 2. 카테고리 생성
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. 저자(Author) 계정으로 로그인 구현은 불가(로그인 엔드포인트 없음)
  // 대신 저자가 작성자로서 게시글을 생성한다 가정 (계정 인증 절차가 없는 것으로 간주)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphaNumeric(8),
      content: RandomGenerator.paragraph()(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. 공격자(Attacker)가 저자가 아닌데 게시글을 임의로 수정 시도할 때
  // 실제 상황이면 여기에 로그인 및 인증 토큰 교체가 필요하지만, 엔드포인트 제공이 없어 단일 connection 으로 가정
  const updateBody: bbsPosts.IUpdate = {
    category_id: category.id,
    title: RandomGenerator.alphaNumeric(8),
    content: RandomGenerator.paragraph()(2),
  };

  await TestValidator.error("비저자/권한 없는 사용자는 게시글 수정 불가")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: updateBody,
    })
  );

  // 5. (옵션) 게시글 원본 내용 불변 검증 불가: 단일 connection에서 실제 계정 인증/스위칭 불가
  // 구현 가능한 단계를 모두 테스트
}

