  /**
   * Main content/body of the post, from the `content` field in the posts
   * table.
   *
   * Includes long-form text, opinion, or analysis. Critical for community
   * discussion.
   */
  content: string;

  /**
   * The timestamp when the post was created, matching `created_at` in the
   * database.
   *
   * Displayed in lists, used for freshness ordering, and necessary for
   * audits.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Last modification timestamp, from `updated_at` in the posts record.
   *
   * Enables edit history tracking and evidence of moderation or typo
   * corrections.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * If present, this timestamp indicates when the post was soft-deleted (not
   * physically removed), in line with moderation and audit business rules.
   *
   * Null if the post is currently visible.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace bbsPosts {
  /**
   * Payload for creating a new post in the discussion board.
   *
   * Links the new post to a specific category, supplies a title and content.
