import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test successful post deletion by the post's author (soft delete or hard delete).
 *
 * This test covers a typical workflow where a user creates a post, then deletes it as the author, and verifies that the deletion is properly reflected by the API.
 *
 * Step-by-step process:
 * 1. Register a user who will be the author and delete the post (using api.functional.bbs.users.post)
 * 2. Create a category for the post (using api.functional.bbs.categories.post)
 * 3. Create a post as the registered user (using api.functional.bbs.posts.post)
 * 4. Delete the post as the same user (using api.functional.bbs.posts.eraseById)
 * 5. Validate that the delete response indicates success (correct type, deleted_at is set)
 * 6. (If possible) Confirm the post no longer appears in further lookups or listings (not possible if such APIs not provided)
 */
export async function test_api_bbs_test_delete_post_by_author(connection: api.IConnection) {
  // 1. Register the user
  const userRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${username}@example.com`;
  const password = RandomGenerator.alphaNumeric(12);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category
  const categoryName = RandomGenerator.alphaNumeric(12);
  const categoryDescription = RandomGenerator.paragraph()(1);
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
    },
  });
  typia.assert(category);

  // 3. Create a post under the category with the registered user as author
  const postTitle = RandomGenerator.paragraph()(1);
  const postContent = RandomGenerator.paragraph()(2);
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      content: postContent,
    },
  });
  typia.assert(post);

  // 4. Delete the post as the author
  const deletedPost = await api.functional.bbs.posts.eraseById(connection, { id: post.id });
  typia.assert(deletedPost);

  // 5. Validation: Verify deleted_at is set (soft delete) or that the returned object marks deletion
  TestValidator.predicate("deleted_at must be present after deletion")(typeof deletedPost.deleted_at === "string" && !!deletedPost.deleted_at);
}

