 * 2. Create a category for the post.
 * 3. Create a post as the registered user.
 * 4. Delete the post as the same user.
 * 5. Validate that the delete response indicates success (correct type, deleted_at is set).
 */
export async function test_api_bbs_test_delete_post_by_author(connection: api.IConnection) {
  // 1. Register the user
  const userRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${username}@example.com`;
  const password = RandomGenerator.alphaNumeric(12);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category
  const categoryName = RandomGenerator.alphaNumeric(12);
  const categoryDescription = RandomGenerator.paragraph()(1);
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
    },
  });
  typia.assert(category);

  // 3. Create a post under the category
  const postTitle = RandomGenerator.paragraph()(1);
  const postContent = RandomGenerator.paragraph()(2);
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      content: postContent,
    },
  });
  typia.assert(post);

  // 4. Delete the post as the author
  const deletedPost = await api.functional.bbs.posts.eraseById(connection, { id: post.id });
  typia.assert(deletedPost);

  // 5. Validate that deleted_at is present (soft delete expected)
  TestValidator.predicate("deleted_at must be present after deletion")(typeof deletedPost.deleted_at === "string" && !!deletedPost.deleted_at);
}

