import { tags } from "typia";

import { IBbsUserRoles } from "./IBbsUserRoles";

/**
 * User profile record (non-sensitive).
 *
 * Implements all fields in users Prisma model except password_hash. Used in
 * administration, moderation, onboarding, audit, and display. Documentation
 * references requirements document and Prisma schema comment.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IBbsUsers = {
  /**
   * Unique identifier for this user (UUID).
   *
   * Primary key in users table. Referenced for moderation, profile editing,
   * and all user-based operations.
   */
  id: string & tags.Format<"uuid">;

  /**
   * User's assigned role (UUID, references user_roles.id).
   *
   * Provides permissions and grants system; links user to allowable actions.
   */
  user_role_id: string & tags.Format<"uuid">;

  /**
   * Unique public handle for the user, visible on posts and comments.
   *
   * As outlined in requirements analysis, serves as user identity for
   * platform interaction.
   */
  username: string;

  /**
   * User's registered email address.
   *
   * Used for notifications, authentication, and support. Not public by
   * default.
   */
  email: string;

  /**
   * Short biographical text the user may choose to display.
   *
   * User-supplied for platform personalization; optional.
   */
  bio?: string | null;

  /**
   * Registration timestamp (ISO8601).
   *
   * When this user joined the platform. Used for audits, sorting, compliance.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp of last profile/account update (ISO8601).
   *
   * Tracks account edit history/maintenance.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Current account state (e.g., active, suspended, banned).
   *
   * Essential for enforcing moderation/business logic as described in
   * requirements.
   */
  status: string;

  /**
   * Full role record for this user (joined on user_role_id).
   *
   * Provides name and description for UI display and permissions checks.
   */
  role: IBbsUserRoles;
};
export namespace IBbsUsers {
  /**
   * User search/list/filter request.
   *
   * Used in user administration and browsing interfaces to retrieve filtered,
   * paginated user lists as described in requirements analysis
   * (moderators/administrators). Properties correspond to search and filter
   * dimensions for the users Prisma table.
   */
  export type IRequest = {
    /**
     * Page number for paginated user listing.
     *
     * Corresponds to IPage.IRequest. Optional; if omitted, results default
     * to the first page. Referenced in user administration and search
     * flows.
     */
    page?: (number & tags.Type<"int32">) | null;

    /**
     * Limitation of records per page for user search.
     *
     * Defaults to 100. Allows tuning the result batch size for moderation
     * or administrative user views.
     */
    limit?: (number & tags.Type<"int32">) | null;

    /**
     * User role filter. Return only users with this role (matches
     * user_roles.id or name).
     *
     * Supports moderator/admin filtering by user class (member,
     * administrator, etc.).
     */
    role?: string | null;

    /**
     * Filter users by account status (e.g., active, suspended, banned).
     *
     * Supports workflow for monitoring and moderation of access levels.
     */
    status?: string | null;

    /**
     * Filter by exact or partial match on user email.
     *
     * Assists in locating specific accounts for administrative intervention
     * or support.
     */
    email?: string | null;

    /**
     * Filter by username (complete or partial match).
     *
     * Used for public moderation, searching individual participants, or
     * audit tasks.
     */
    username?: string | null;

    /**
     * Filter for users registered after the given timestamp (ISO8601
     * format).
     *
     * Used to find recent registrations or perform time-based audits.
     */
    registered_after?: (string & tags.Format<"date-time">) | null;

    /**
     * Filter for users registered before the given timestamp (ISO8601
     * format).
     *
     * Used to look up users registered before a certain date.
     */
    registered_before?: (string & tags.Format<"date-time">) | null;

    /**
     * Sort order (username, email, created_at).
     *
     * For user management screens, allows control of user list ordering.
     */
    sort_by?: "username" | "email" | "created_at" | null;

    /**
     * Sorting direction for user list.
     *
     * 'asc' for ascending, 'desc' for descending.
     */
    sort_order?: "asc" | "desc" | null;
  };

  /**
   * Registration payload for new users.
   *
   * Implements onboarding/registration parameters as described in
   * requirements and reflected in Prisma users table. Only non-sensitive
   * initial account data permitted.
   */
  export type ICreate = {
    /**
     * Desired username (must be unique).
     *
     * Mandatory for registration and public identity, per requirements
     * analysis.
     */
    username: string;

    /**
     * Email address to register (unique, notified on events).
     *
     * Used for login and notifications.
     */
    email: string;

    /**
     * Initial user password (supplied in plain form, will be hashed on
     * storage).
     *
     * Never returned in API. Enforced by strong password policies.
     */
    password: string;

    /**
     * Optional biographical text.
     *
     * User profile customization, as outlined in requirements.
     */
    bio?: string | null;

    /**
     * Role assignment (UUID from user_roles.id).
     *
     * Specifies initial user permissions (e.g., member, moderator,
     * administrator). Determines access scope for new account creation.
     */
