  // We'll create a list with varying usernames, email domains, roles, and statuses.
  const userRoleAdminId: string = typia.random<string & tags.Format<"uuid">>();
  const userRoleMemberId: string = typia.random<string & tags.Format<"uuid">>();

  // Make one admin, others regular members
  const users = [
    {
