      email: "bob@somewhere.com",
      password: "Memb3rPass456",
      bio: null,
      role_id: userRoleMemberId,
    },
    {
      username: "carl.user",
      email: "carl@boardcorp.com",
      password: "Carls1e!",
      bio: "A power user.",
      role_id: userRoleMemberId,
    },
    {
      username: "dora89",
      email: "dora@anothermail.com",
      password: "Dora2024$",
      role_id: userRoleMemberId,
    },
    {
      username: "emily_x",
      email: "emily.x@boardcorp.com",
      password: "EmilyPW!2022",
      status: "suspended",
      role_id: userRoleMemberId,
    },
  ];
  const created = [];
  for (const user of users) {
    // Add status if provided
    const createBody: IBbsUsers.ICreate = {
      username: user.username,
      email: user.email,
      password: user.password,
      bio: "bio" in user ? user.bio ?? null : undefined,
      role_id: user.role_id,
      // Cannot set status on create (not supported in DTO), so only provide fields as defined.
    };
    const result = await api.functional.bbs.users.post(connection, { body: createBody });
    typia.assert(result);
    created.push(result);
  }

  // --- Pick one of the created as admin (simulate -- since no login API exists, assume connection is privileged for now).

  // 2. Compose filter: search for username containing 'user', email domain '@boardcorp.com', and (if possible) status = 'active'.
  const usernameSubstring = "user";
  const emailDomain = "@boardcorp.com";
  // Find a real 'status' by inspecting a created user, fallback to undefined.
  const activeStatus = created.find(u => u.status === "active")?.status ?? (created.length ? created[0].status : undefined);

  // Use a limit of 2 per page (smaller than the total number to trigger pagination)
  const pageLimit = 2;

