  // 5. Assert pagination correct
  TestValidator.equals("limit")(userListResp.pagination.limit)(pageLimit);
  TestValidator.equals("page")(userListResp.pagination.current)(1);
  TestValidator.predicate("records >= 0")(userListResp.pagination.records >= 0);
  TestValidator.predicate("pages >= 1")(userListResp.pagination.pages >= 1);

  // 6. (Boundary) Request next page (if more pages exist)
  if (userListResp.pagination.pages > 1) {
    const nextPageResp = await api.functional.bbs.users.patch(connection, {
      body: {
        username: usernameSubstring,
