      TestValidator.predicate("email domain matches")(user.email.endsWith("boardcorp.com"));
      TestValidator.equals("status matches")(user.status)(activeStatus);
    }
  }

  // 7. Negative filter (no users returned)
  const negResp = await api.functional.bbs.users.patch(connection, {
    body: {
      username: "thisuserdoesnotexist__test",
      limit: pageLimit,
      page: 1,
    } satisfies IBbsUsers.IRequest,
  });
