 *
 * Scenario:
 * - Authenticate as an administrator (assume "connection" already provides admin rights for the test).
 * - Attempt to list BBS users with invalid filter parameters:
 *   - Use a date range with unsupported format in "registered_after" or "registered_before" (e.g., a random string instead of ISO8601 date-time).
 *   - Pass an invalid account status that is not recognized by the system (e.g., "ghostmode").
 * - Confirm that the API rejects these requests with proper validation errors.
 *
 * Steps:
 * 1. Call user listing API with an unsupported (malformed) date for "registered_after" (e.g., "not-a-date").
 * 2. Expect an error to be thrown and catch it.
 * 3. Call user listing API with an invalid status value (e.g., "ghostmode").
 * 4. Expect an error to be thrown and catch it.
 */
export async function test_api_bbs_test_list_users_with_invalid_filter_type(connection: api.IConnection) {
  // 1. Use an invalid date string for registered_after
  await TestValidator.error("malformed date string for registered_after")(
    async () => {
      await api.functional.bbs.users.patch(connection, {
        body: {
          registered_after: "not-a-date"
        }
      });
    }
  );

  // 2. Use an invalid status string
  await TestValidator.error("unsupported status value")(
    async () => {
      await api.functional.bbs.users.patch(connection, {
        body: {
          status: "ghostmode"
        }
      });
    }
  );
}

