import type { IPageIBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUsers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that the user listing API returns validation errors for invalid filter types or values.
 *
 * This test ensures that privileged users (administrators) requesting user lists
 * with malformed filters (such as incorrect date formats or unknown status values)
 * receive proper validation errors. Correct filter validation is essential for
 * robust backend APIs, preventing ambiguous results and ensuring clear diagnostics
 * for frontend and admin tooling.
 *
 * This test covers two error scenarios:
 * 1. The 'registered_after' filter is given in an invalid (non-ISO8601) format.
 * 2. The 'status' filter is set to an unsupported value not recognized by the system.
 *
 * Steps:
 * 1. Attempt to list users with a malformed 'registered_after' filter (e.g., "not-a-date").
 *    - Verify that the API throws a validation error.
 * 2. Attempt to list users with an invalid status value (e.g., "ghostmode").
 *    - Verify that the API throws a validation error.
 */
export async function test_api_bbs_test_list_users_with_invalid_filter_type(
  connection: api.IConnection,
) {
  // 1. Use an invalid date string for 'registered_after'
  await TestValidator.error("malformed date string for registered_after")(
    async () => {
      await api.functional.bbs.users.patch(connection, {
        body: {
          registered_after: "not-a-date",
        },
      });
    },
  );

  // 2. Use an invalid (unsupported) status string
  await TestValidator.error("unsupported status value")(
    async () => {
      await api.functional.bbs.users.patch(connection, {
        body: {
          status: "ghostmode",
        },
      });
    },
  );
}

