import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IPageIBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUsers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate access control on user list search: permission denied for standard user.
 *
 * This test ensures access control for user listing is enforced by checking
 * non-privileged users (standard roles) cannot retrieve the paginated/searchable user list.
 *
 * Business context: According to system documentation, the /bbs/users PATCH
 * endpoint is reserved for admins/moderators so that only privileged actors can
 * view user directory for audit, support, or moderation tasks. Regular users
 * must never be able to enumerate the user base for privacy, compliance, and
 * security. This test confirms that RBAC and route guards are correctly applied.
 *
 * Workflow:
 * 1. Register a regular (non-privileged) user using /bbs/users POST.
 * 2. Attempt to submit a user list/search (PATCH /bbs/users) authenticated as this user.
 * 3. Confirm the request is rejected with an error (permission denied/forbidden).
 */
export async function test_api_bbs_test_list_users_without_privileges_permission_denied(connection: api.IConnection) {
  // 1. Register standard user
  const regularUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      bio: RandomGenerator.paragraph()(),
      role_id: typia.random<string & tags.Format<"uuid">>()
    }
  });
  typia.assert(regularUser);

  // NOTE: No privileged authentication endpoints are available,
  // so no explicit login; assume token issued on registration or connection

  // 2. Attempt to list users as regular user
  await TestValidator.error("permission denied for non-privileged user")(
    async () => {
      await api.functional.bbs.users.patch(connection, {
        body: {
          page: 1,
          limit: 10,
        }
      });
    }
  );
}

