import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that an administrator can retrieve the full public profile of a specific user.
 *
 * This test verifies administrative access to detailed user profiles, ensuring sensitive fields (like credentials) are omitted, while all required public and audit information is returned correctly. Edge cases like long bios and special characters should also be handled.
 *
 * Steps:
 * 1. Register a new user with a long bio and special characters using the user registration endpoint.
 * 2. (Assumes admin authentication context is established via connection.)
 * 3. As administrator, request the profile of the newly registered user by their UUID using the /bbs/users/{id} endpoint.
 * 4. Validate that the response matches the expected fields (id, user_role_id, username, email, bio, created_at, updated_at, status, role), but never includes credentials (such as password hash or password).
 * 5. Check that the returned bio matches the input, including any long text or special characters provided.
 * 6. Validate that the returned role information is complete and consistent (should match any role info provided/referenced at creation or system default).
 * 7. Check audit fields and status are well-formed, and that all data respects TypeScript types (using typia.assert).
 */
export async function test_api_bbs_test_get_user_profile_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new user with a long bio and special characters
  const longBio =
    'This is a very long bio 😃 with special characters !@#$%^&*()_+ and unicode 雨, covering edge cases for bio fields.' +
    ' '.repeat(512);
  const randomEmail = typia.random<string & tags.Format<"email">>();
  const uniqueUsername = `testuser_${RandomGenerator.alphabets(10)}`;
  // Create user as admin (can assign any role as needed, using existing UUID for role)
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: uniqueUsername,
      email: randomEmail,
      password: "Secure!P@ssw0rd-12345",
      bio: longBio,
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. As admin, fetch the full user profile by UUID
  const profile = await api.functional.bbs.users.getById(connection, {
    id: user.id,
  });
  typia.assert(profile);

  // 3. Check returned fields
  TestValidator.equals("user id")(profile.id)(user.id);
  TestValidator.equals("user role id")(profile.user_role_id)(user.user_role_id);
  TestValidator.equals("username")(profile.username)(user.username);
  TestValidator.equals("email")(profile.email)(user.email);
  TestValidator.equals("bio matches full content")(profile.bio)(longBio);
  TestValidator.equals("created_at exists")(typeof profile.created_at === "string")(true);
  TestValidator.equals("updated_at exists")(typeof profile.updated_at === "string")(true);
  TestValidator.equals("status exists")(typeof profile.status === "string")(true);
  // 4. Check nested role information is present and well-formed
  typia.assert(profile.role);
  TestValidator.equals("role id matches")(profile.role.id)(profile.user_role_id);
  TestValidator.equals("role name exists")(typeof profile.role.name === "string")(true);
  TestValidator.equals("role desc exists")(typeof profile.role.description === "string")(true);
  // 5. Security: ensure credential fields are not present (by TypeScript constraints, password not in IBbsUsers)
  TestValidator.predicate("no credentials exposed")(!("password_hash" in profile));
}

