import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that a non-privileged user cannot access another user's profile (forbidden access test).
 *
 * Business context:
 * Access to user profiles by user ID is restricted to privileged roles (e.g., moderator, administrator), and a standard user should not be able to access profiles of other users for privacy/security reasons. This test ensures that unchecked access is blocked as designed.
 *
 * Test process:
 * 1. Register two standard users (userA and userB), each with the default/lowest user role.
 * 2. Attempt to authenticate or act as userA (simulate if no login endpoint), and request userB's profile by UUID.
 * 3. Expect the API to reject the request with a forbidden/permission denied error. Error handling must catch and assert this is an authorization failure.
 */
export async function test_api_bbs_test_get_user_profile_unauthorized_access(
  connection: api.IConnection,
) {
  // Step 1: Register two standard users
  const userRoleId = typia.random<string & tags.Format<"uuid">>();

  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ssword1!",
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ssword1!",
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // Step 2: (Assume authentication context is userA; if not possible, use fresh connection after registration)
  // Try to access userB's profile as userA (unprivileged)
  await TestValidator.error("Non-admin user should not access another user's profile")(
    async () => {
      await api.functional.bbs.users.getById(connection, {
        id: userB.id,
      });
    },
  );
}

