import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test successful creation of a user account via admin privileges.
 *
 * This test covers the significant workflow of programmatically registering a new user profile with all valid fields as an administrator. It ensures that:
 * - The admin can list available user roles and select an existing role for assignment
 * - The admin can submit all required registration fields (unique username, valid email, strong password, assigned user_role_id) and optional fields (bio)
 * - The resulting user profile is returned with all non-sensitive data (excluding the password)
 *
 * Steps:
 * 1. List valid user roles using the userRoles listing endpoint. Confirm at least one available role.
 * 2. Generate valid, unique username, email, and strong password
 * 3. Register a new user with well-formed data, including one real user_role_id and an optional bio
 * 4. Verify the returned profile matches submitted values (except password field; must not appear)
 */
export async function test_api_bbs_test_create_user_with_valid_data(
  connection: api.IConnection,
) {
  // 1. List valid user roles (needed to get a real, existing role_id)
  const rolesResult = await api.functional.bbs.userRoles.patch(connection, {
    body: {}, // empty filter gets all
  });
  typia.assert(rolesResult);
  TestValidator.predicate("should have available roles")(Array.isArray(rolesResult.data) && rolesResult.data.length > 0);
  const chosenRole = RandomGenerator.pick(rolesResult.data);

  // 2. Generate unique username, valid email, strong password, optional bio
  const username = RandomGenerator.alphaNumeric(10);
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const bio = RandomGenerator.paragraph()();

  // 3. Register a new user with well-formed data
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio,
      role_id: chosenRole.id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 4. Validate returned profile (should match input, password not included)
  TestValidator.equals("username matches")(user.username)(username);
  TestValidator.equals("email matches")(user.email)(email);
  TestValidator.equals("bio matches")(user.bio)(bio);
  TestValidator.equals("role_id matches")(user.user_role_id)(chosenRole.id);
  TestValidator.equals("role object matches")(user.role)(chosenRole);
  TestValidator.predicate("Password not present in response")(!('password' in user));
}

