 * 2. Register an initial user (user1) with unique username/email (happy path).
 * 3. Attempt to register a new user (user2) with the same email but a fresh username (should fail).
 * 4. Attempt to register another user (user3) with the same username but a fresh email (should fail).
 * 5. Validate that both attempts in steps 3 and 4 return errors indicating uniqueness constraint violations.
 */
export async function test_api_bbs_test_create_user_with_duplicate_email_or_username(
  connection: api.IConnection,
) {
