 * Validate that user registration fails when supplied with invalid role references or malformed email/password/username.
 *
 * This test ensures the backend API's user registration endpoint enforces validation for:
 * 1. Role reference integrity (non-existent or invalid role_uuid)
 * 2. Proper email format and uniqueness
 * 3. Password pattern and minimum policy compliance
 * 4. Username presence and constraints
 *
 * Test logic and steps:
 * 1. Fetch a list of valid user roles via the userRoles PATCH endpoint (dependency), saving at least one known valid role id. 
 *    Construct an invalid role UUID that does not appear in the list for invalid role testing.
 * 2. Attempt user registration with:
 *     a. An invalid (non-existent) role_id but otherwise valid input
 *     b. Invalid/malformed email but valid password/username/role
 *     c. Invalid/malformed password but valid email/username/role
 *     d. Invalid/empty username but valid email/password/role
 *
 * For each case:
 *  a. Call the user registration endpoint
 *  b. Expect the API to return an error, and confirm failure with TestValidator.error()
 *
 * Extra edge case: also test with multiple simultaneous input validation failures (e.g., bad email + bad password) to confirm API returns error.
 *
 * Each error path should be independently confirmed to fail properly and not result in user creation.
 */
export async function test_api_bbs_test_create_user_with_invalid_role_or_format(
  connection: api.IConnection,
) {
  // 1. Fetch valid user roles
  const rolesPage = await api.functional.bbs.userRoles.patch(connection, {
    body: {},
  });
  typia.assert(rolesPage);
  TestValidator.predicate("roles should exist")(rolesPage.data.length > 0);
  const validRoleId = rolesPage.data[0].id;

  // 2. Construct an invalid uuid not in current roles
  let invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  while (rolesPage.data.some(role => role.id === invalidRoleId)) {
    invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  }

  // 3a. Attempt with invalid role_id (otherwise valid input)
  TestValidator.error("invalid role reference")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
