import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test that a user can successfully update their own profile using valid data for username, email, bio, and role, ensuring that all integrity and uniqueness constraints are respected.
 *
 * Business Context:
 * - A user who is already registered with a valid profile and role wants to update their account information (username, email, bio, and role).
 * - Usernames and emails must remain unique at all times.
 * - Some fields are optional, but if provided, changes must be reflected in the updated profile.
 * - Role changes are allowed provided the chosen role_id exists and is valid (for this test, pick or generate a new UUID for the role distinct from the original one).
 *
 * Workflow:
 * 1. Register a new user account as a test subject (using the dependency).
 * 2. Pick/generate new valid values for username, email, bio, and a new role_id (different from the initial one).
 * 3. Update the user's profile (as themselves) using a valid PUT /bbs/users/{id} call, passing only changed information.
 * 4. Validate that (a) the API call succeeds, (b) the returned user profile reflects the new values, (c) unchanged fields remain correct, and (d) the uniqueness of username/email is maintained.
 */
export async function test_api_bbs_test_update_user_profile_as_self_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user
  const initialRoleId = typia.random<string & tags.Format<"uuid">>();
  const userRegistration = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    bio: RandomGenerator.paragraph()(),
    role_id: initialRoleId
  } satisfies IBbsUsers.ICreate;
  const user = await api.functional.bbs.users.post(connection, { body: userRegistration });
  typia.assert(user);

  // 2. Prepare new values (simulate role change too)
  const newUsername = RandomGenerator.alphaNumeric(10);
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newBio = RandomGenerator.paragraph()();
  // Generate a new role_id different from the initial one
  let newRoleId = typia.random<string & tags.Format<"uuid">>();
  while (newRoleId === initialRoleId) {
    newRoleId = typia.random<string & tags.Format<"uuid">>();
  }

  // 3. Update the user profile as themselves
  const updatedInput = {
    username: newUsername,
    email: newEmail,
    bio: newBio,
    role_id: newRoleId
  } satisfies IBbsUsers.IUpdate;
  const updated = await api.functional.bbs.users.putById(connection, { id: user.id, body: updatedInput });
  typia.assert(updated);

  // 4. Validate output
  TestValidator.equals("user id matches")(updated.id)(user.id);
  TestValidator.equals("username updated")(updated.username)(newUsername);
  TestValidator.equals("email updated")(updated.email)(newEmail);
  TestValidator.equals("bio updated")(updated.bio)(newBio);
  TestValidator.equals("role id updated")(updated.user_role_id)(newRoleId);
  TestValidator.equals("status unchanged")(updated.status)(user.status);
  TestValidator.predicate("updated_at is newer")(new Date(updated.updated_at) > new Date(user.updated_at));
  TestValidator.notEquals("old username")(updated.username)(user.username);
  TestValidator.notEquals("old email")(updated.email)(user.email);
}

