   * Update payload for user profile/account.
   *
   * Implements the user and administrative self-update, moderation, and
   * profile-edit flows described in requirements analysis and Prisma schema.
   * All fields optional for PATCH/PUT semantics.
   */
  export type IUpdate = {
    /**
     * New username, if changing. Must remain unique.
     *
     * May only be updated by the user or privileged roles.
     */
    username?: string | null;

    /**
     * Email address for changing login/notifications. Must remain unique.
     *
     * Admin or user-only operation.
     */
    email?: string | null;

    /**
     * Updated bio (profile description).
     *
     * Used for user self-edit or admin-moderator workflow.
     */
    bio?: string | null;

    /**
     * Status value (active, suspended, banned, etc).
     *
     * May be set by authorized roles per moderation/business rules.
     */
    status?: string | null;

    /**
     * New role assignment for the user (user_roles.id).
     *
     * For admin-only role changes (e.g., promotion to
     * moderator/administrator).
     */
    role_id?: (string & tags.Format<"uuid">) | null;
  };
}

