import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Attempt to update another user's profile as a regular (non-admin, non-target) user, expecting a forbidden error.
 *
 * This test validates the permission system by:
 * - Registering two users: Alice and Bob (with minimal standard roles)
 * - Simulating Bob attempting to update Alice's profile (Bob is NOT admin and NOT Alice)
 * - Submitting a valid update payload as Bob
 * - Ensuring a permission denied or forbidden result is returned (operation NOT allowed)
 *
 * Steps:
 * 1. Register Alice (collect her id and role id)
 * 2. Register Bob (the offender who will try to edit Alice)
 * 3. (If system has login: simulate Bob as current user, else just use context as Bob)
 * 4. Bob attempts to update Alice's username or bio with valid data
 * 5. Assert that a permission error/forbidden error is returned (cannot update another user's profile without sufficient privileges)
 */
export async function test_api_bbs_test_update_other_user_profile_without_admin_permission(
  connection: api.IConnection,
) {
  // 1. Register Alice
  const aliceRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const alice: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      role_id: aliceRoleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(alice);

  // 2. Register Bob
  const bobRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const bob: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      role_id: bobRoleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(bob);

  // 3. (If applicable) Context is now Bob: assume connection as Bob (system manages session after call to users.post)
  // 4. Bob attempts to update Alice's account
  await TestValidator.error("Bob should NOT be able to update Alice's profile")(
    () =>
      api.functional.bbs.users.putById(connection, {
        id: alice.id,
        body: {
          bio: "This should not succeed!",
        } satisfies IBbsUsers.IUpdate,
      })
  );
}

