 * 2. Attempt to update the first user's email to the second user's email (should fail with uniqueness error).
 * 3. Attempt to update the first user's username to the second user's username (should fail with uniqueness error).
 * 4. Verify that no changes have been made to the first user's original profile after each failed attempt.
 */
export async function test_api_bbs_test_update_user_profile_with_duplicate_email_or_username(connection: api.IConnection) {
