 * 2. Register a normal (test) user with that role (who will attempt the deletion).
 * 3. Register another (target) user with that role (who will be the unauthorized deletion target).
 * 4. Attempt to soft-delete the target user, authenticating as the test user (not as admin and not as the target owner).
 * 5. Confirm an error occurs due to insufficient permissions.
 */
export async function test_api_bbs_test_attempt_soft_delete_by_non_admin_permission_denied(connection: api.IConnection) {
