  // (Normally you would fetch/create roles, but here, simulate two users with the same role)
  // Generate dummy role UUID to use for standard users
  const userRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Register the test user (who will be the unauthorized actor)
  const testUserEmail = typia.random<string & tags.Format<"email">>();
  const testUser = await api.functional.bbs.users.post(connection, {
    body: {
