  const targetUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: `targetuser_${RandomGenerator.alphaNumeric(6)}`,
      email: targetUserEmail,
      password: "TargetUserPassw0rd!",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
