import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing all direct replies to a valid parent comment with pagination.
 *
 * This test covers the workflow of registering a user, creating a post and category,
 * adding a parent comment, and creating several direct replies and a nested noise reply.
 * Then, lists the replies to the parent comment with different pagination/filter settings,
 * checking that only direct children are returned (not deeper nested), content matches,
 * ordering/integrity is correct, pagination metadata matches, and for another comment
 * with no replies, an empty paginated list is returned.
 *
 * Steps:
 * 1. Register user
 * 2. Create category
 * 3. Create post
 * 4. Add parent comment
 * 5. Create several direct replies
 * 6. Create a nested (deep) reply to the first reply
 * 7. List replies for parent comment with various pagination (default, limit=2, etc.)
 * 8. Check reply data (only direct children), pagination, and user/content integrity
 * 9. List replies for another (no-child) comment, confirm results empty
 */
export async function test_api_bbs_test_list_replies_to_comment_with_valid_parent_comment_and_pagination(connection: api.IConnection) {
  // 1. Register new user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!_" + RandomGenerator.alphaNumeric(6),
      // Randomly choose a role/privilege for general member (simulate basic role)
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: RandomGenerator.paragraph()(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create post in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "This is the parent comment.",
    } satisfies bbsComments.ICreate,
  });
  typia.assert(parentComment);

  // 5. Create several direct replies to parentComment
  const replyCount = 3;
  const directReplies: IBbsCommentReply[] = [];
  for (let i = 0; i < replyCount; ++i) {
    const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: parentComment.id,
      body: {
        content: `Direct reply ${i + 1}`,
      },
    });
    typia.assert(reply);
    directReplies.push(reply);
  }

  // 6. Create a nested reply to the first direct reply (should not be included in direct list)
  const noiseNestedReply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: directReplies[0].id,
    body: {
      content: "Nested reply not a direct child.",
    },
  });
  typia.assert(noiseNestedReply);

  // 7. List replies for the parent comment: default pagination
  const replyListDefault = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: {}, // default: page/limit undefined
  });
  typia.assert(replyListDefault);
  // 8a. Validate reply list contains only direct children and not the nested reply
  TestValidator.equals("reply count matches")(replyListDefault.data.length)(directReplies.length);
  for (const reply of replyListDefault.data) {
    // Only direct replies to parent
    TestValidator.equals("parent_id matches")(reply.parent_id)(parentComment.id);
    // Not the noise nested reply
    TestValidator.notEquals("not the noise nested reply")(reply.id)(noiseNestedReply.id);
    // Content matches one of the created direct replies
    TestValidator.predicate("reply content matches one of originals")(directReplies.some(dr => dr.id === reply.id && dr.content === reply.content));
    // Author user_id matches creator
    TestValidator.equals("reply user matches")(reply.user_id)(user.id);
  }

  // 8b. Validate pagination
  TestValidator.equals("pagination count matches")(replyListDefault.pagination.records)(directReplies.length);
  TestValidator.equals("pagination limit matches")(replyListDefault.pagination.limit)(100);
  TestValidator.equals("pagination page matches")(replyListDefault.pagination.current)(1);

  // 7b. List with page=1, limit=2
  const replyListPage1 = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(replyListPage1);
  TestValidator.equals("page 1 contains 2 replies")(replyListPage1.data.length)(2);
  TestValidator.equals("pagination current=1")(replyListPage1.pagination.current)(1);
  TestValidator.equals("pagination limit=2")(replyListPage1.pagination.limit)(2);
  TestValidator.equals("pagination total=3")(replyListPage1.pagination.records)(3);
  TestValidator.equals("pagination pages=2")(replyListPage1.pagination.pages)(2);

  // 7c. List with page=2, limit=2 (should contain the third reply only)
  const replyListPage2 = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      page: 2,
      limit: 2,
    },
  });
  typia.assert(replyListPage2);
  TestValidator.equals("page 2 contains 1 reply")(replyListPage2.data.length)(1);
  TestValidator.equals("pagination current=2")(replyListPage2.pagination.current)(2);
  TestValidator.equals("pagination limit=2")(replyListPage2.pagination.limit)(2);

  // 9. Make another comment on the post and check replies is empty
  const noReplyParentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "This comment should have no child replies.",
    } satisfies bbsComments.ICreate,
  });
  typia.assert(noReplyParentComment);
  const noReplyList = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: noReplyParentComment.id,
    body: {},
  });
  typia.assert(noReplyList);
  TestValidator.equals("comment with no replies returns empty data")(noReplyList.data.length)(0);
  TestValidator.equals("pagination total records is 0")(noReplyList.pagination.records)(0);
}

