import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error handling and access control when listing replies to a deleted (soft-deleted) comment.
 *
 * This test verifies that replies to a comment cannot be listed if the parent comment is deleted. It ensures
the backend enforces moderation logic, denying unauthorized access or logical violations for soft-deleted parent comments.
 *
 * Steps:
 * 1. Register a user (to perform all following actions as an authenticated actor).
 * 2. Create a new category (so a post can be created inside it).
 * 3. Create a post in the new category (the comment thread root).
 * 4. Add a parent comment (top-level, non-reply) to the post.
 * 5. Soft-delete this parent comment using the comment deletion endpoint.
 * 6. Attempt to list direct replies to the deleted parent comment via the replies-for-comment API.
 * 7. Expect an error or empty result, confirming no replies are returned and that the system enforces proper access/business rules.
 */
export async function test_api_bbs_test_list_replies_to_deleted_parent_comment(
  connection: api.IConnection,
) {
  // 1. Register a user.
  // (Assume we are using a regular member role—the test focuses on logical access, not advanced role nuances.)
  // Since role must be a valid UUID, create a dummy one or fetch/minimum role for tests.
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const username: string = RandomGenerator.alphabets(8);
  const email: string = `${username}@example.com`;
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password: "TestPassword123!",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
