import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test successful retrieval of reply details for a valid reply under a parent comment.
 *
 * This test verifies that after a user registers, creates a post, adds a comment, and then adds a direct reply to that comment, the system correctly allows fetching the reply details using the parent and reply IDs. The test ensures:
 *   - All setup data are valid and created as expected.
 *   - The response for fetching the reply details contains all necessary fields and matches the values of the created reply (including proper parent-child linkage).
 *   - No sensitive or moderator-only fields are present in the returned data (leak protection).
 *
 * Steps:
 * 1. Register a new user (only fields allowed by registration DTO).
 * 2. Create a new category to place the post.
 * 3. Create a new post in this category by the user.
 * 4. Add a first-level comment to the post.
 * 5. Create a reply to that comment (nested comment).
 * 6. Retrieve the reply using the (parent) comment ID and reply ID via getByCommentidAndId.
 * 7. Assert that the returned data matches the reply record (ID, content, parent-child linkage, timestamps).
 */
export async function test_api_bbs_test_get_reply_details_with_valid_reply_and_permission(connection: api.IConnection) {
  // 1. Register user
  const roleId = typia.random<string & tags.Format<"uuid">>(); // Simulate any valid role UUID
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssword123", // Acceptable dummy password
      role_id: roleId,
      bio: null
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()()
    } satisfies bbsCategories.ICreate
  });
  typia.assert(category);

  // 3. Create post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.paragraph()()
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 4. Add first-level comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()()(),
      parent_id: null
    } satisfies bbsComments.ICreate
  });
  typia.assert(comment);

  // 5. Add reply (nested comment)
  const replyContent = RandomGenerator.content()()();
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: replyContent
    } satisfies IBbsCommentReply.ICreate
  });
  typia.assert(reply);
  TestValidator.equals("reply parent_id links to parent comment")(reply.parent_id)(comment.id);
  TestValidator.equals("reply content matches")(reply.content)(replyContent);

  // 6. Retrieve reply details
  const output = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id
  });
  typia.assert(output);

  // 7. Validate returned details
  TestValidator.equals("reply id")(output.id)(reply.id);
  TestValidator.equals("reply parent_id")(output.parent_id)(comment.id);
  TestValidator.equals("reply content")(output.content)(replyContent);
  TestValidator.equals("reply user_id")(output.user_id)(user.id);
  TestValidator.equals("reply post_id")(output.post_id)(post.id);

  // Additional field checks (timestamps, proper non-leakage of sensitive fields)
  TestValidator.predicate("created_at present and ISO format")(!!output.created_at && !Number.isNaN(Date.parse(output.created_at)));
  TestValidator.predicate("updated_at present and ISO format")(!!output.updated_at && !Number.isNaN(Date.parse(output.updated_at)));
  // No password, moderation, or hidden fields (by DTO contract, so typia.assert suffices)
}

