import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test that fetching a reply (nested comment) after it has been soft-deleted does not leak its content or must provide an appropriate error.
 *
 * Business context: Replies in a BBS can be soft-deleted rather than hard-deleted for audit/moderation purposes. When a soft-deleted reply is accessed, its details should not be shown to ordinary users, or an appropriate error should be raised. This test establishes that expected behavior.
 *
 * Steps:
 * 1. Register a BBS user (with required fields).
 * 2. Create a BBS category (board topic) for posting.
 * 3. Create a post in the created category as the registered user.
 * 4. Add a top-level comment to the post.
 * 5. Add a nested reply to the comment.
 * 6. Soft-delete the reply (nested comment) via the appropriate API.
 * 7. Attempt to fetch the reply details via GET on the reply resource.
 * 8. Verify that either (a) an error is thrown, or (b) the response contains a deleted_at timestamp and no content (content empty or null). The system must never expose the deleted reply content.
 *
 * This test ensures moderated (soft-deleted) content is protected from inappropriate display/access.
 */
export async function test_api_bbs_comments_test_get_reply_details_for_deleted_reply(
  connection: api.IConnection,
) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.email(),
      password: "Password123!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: RandomGenerator.paragraph()(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Create a parent comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. Create a reply (nested comment)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.content()()(),
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. Soft-delete the reply
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });

  // 7. Attempt to GET the reply's details: system should not leak content
  await TestValidator.error("Soft-deleted reply should not be accessible")(
    async () => {
      await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
      });
    },
  );
}

