import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsCommentReply } from "../../../../structures/IBbsCommentReply";

/**
 * Get information for a specific reply to a comment (comments table, threaded
 * comment).
 *
 * This operation fetches the details of a specific reply to a given parent
 * comment, leveraging the 'comments' table's self-referential structure. It
 * checks that the reply exists, has its 'parent_id' set to the specified
 * 'commentId', and is not marked as deleted (soft delete logic).
 *
 * Useful for showing reply detail pages or in-line replies in the UI. Access
 * control ensures that deleted replies or those hidden for moderation are not
 * shown to ordinary users. The response includes all major comment fields
 * (content, author, created time, votes, etc.), as well as any relevant
 * metadata for thread navigation and moderation.
 *
 * @param props.connection
 * @param props.commentId Parent comment's ID (pid for threaded reply context).
 * @param props.id Reply comment's ID to retrieve.
 * @path /bbs/comments/:commentId/comments/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getByCommentidAndId(
  connection: IConnection,
  props: getByCommentidAndId.Props,
): Promise<getByCommentidAndId.Response> {
  return !!connection.simulate
    ? getByCommentidAndId.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getByCommentidAndId.METADATA,
          path: getByCommentidAndId.path(props),
          status: null,
        },
      );
}
export namespace getByCommentidAndId {
  export type Props = {
    /** Parent comment's ID (pid for threaded reply context). */
    commentId: string & tags.Format<"uuid">;

    /** Reply comment's ID to retrieve. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IBbsCommentReply;

  export const METADATA = {
    method: "GET",
    path: "/bbs/comments/:commentId/comments/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/comments/${encodeURIComponent(props.commentId ?? "null")}/comments/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IBbsCommentReply => typia.random<IBbsCommentReply>(g);
  export const simulate = (
    connection: IConnection,
    props: getByCommentidAndId.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getByCommentidAndId.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("commentId")(() => typia.assert(props.commentId));
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

