import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate error response for retrieving a non-existent comment reply or using mismatched parent/reply IDs.
 *
 * This test checks if the system properly handles negative scenarios when fetching a reply to a comment:
 *
 * 1. Attempting to request a reply with random (definitely non-existent) commentId and id values (UUIDs).
 *    - Ensures the API returns a not-found (or appropriate error) when queried with IDs not present in the DB.
 * 2. Sending requests with mismatched commentId and id parameters so that the reply does not actually belong to the specified parent comment (not implemented here, as the environment does not provide creation APIs).
 *
