import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test the successful creation of a nested reply to an existing comment by an authenticated user, ensuring full business context and data associations.
 *
 * Business context:
 * This workflow exercises the ability of a registered and authenticated user to create a threaded (nested) reply via the /bbs/comments/{commentId}/comments endpoint. It validates the association to the parent comment, appropriate ownership, and integrity of the reply data (author, timestamp).
 *
 * Process steps:
 * 1. Register a user account for use in the test
 * 2. Create a post category for organizing the discussion
 * 3. Create a post within that category, authored by the registered user
 * 4. Add a top-level comment to the post
 * 5. Submit a reply to the above comment via /bbs/comments/{commentId}/comments
 * 6. Verify the returned reply object:
 *    - parent_id matches the original comment ID
 *    - post_id corresponds to the thread
 *    - user_id is set to the newly registered user
 *    - content and timestamps are present and correct
 */
export async function test_api_bbs_test_create_reply_to_comment_with_valid_auth_and_data(
  connection: api.IConnection,
) {
  // 1. Register a user (including simulated/unique username and email)
  const userRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(12);
  const email = `${username}@example.com`;
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password: RandomGenerator.alphaNumeric(14),
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);
  TestValidator.equals("username matches")(user.username)(username);
  TestValidator.equals("email matches")(user.email)(email);

  // 2. Create a category
  const categoryInput = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  } satisfies bbsCategories.ICreate;
  const category = await api.functional.bbs.categories.post(connection, {
    body: categoryInput,
  });
  typia.assert(category);
  TestValidator.equals("category name matches")(category.name)(categoryInput.name);

  // 3. Create a post in the new category
  const postInput = {
    category_id: category.id,
    title: RandomGenerator.paragraph()().slice(0, 50),
    content: RandomGenerator.content()()(),
  } satisfies bbsPosts.ICreate;
  const post = await api.functional.bbs.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);
  TestValidator.equals("post category matches")(post.category_id)(category.id);

  // 4. Add a top-level comment to the post
  const commentInput = {
    content: RandomGenerator.paragraph()(),
  } satisfies bbsComments.ICreate;
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: commentInput,
  });
  typia.assert(comment);
  TestValidator.equals("comment post ID matches")(comment.post_id)(post.id);

  // 5. Submit a reply (nested comment) to the above comment
  const replyContent = RandomGenerator.content()()();
  const replyInput = {
    content: replyContent,
  } satisfies IBbsCommentReply.ICreate;
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: replyInput,
  });
  typia.assert(reply);

  // 6. Assertions on the reply structure and associations
  TestValidator.equals("reply's parent_id matches comment")(reply.parent_id)(comment.id);
  TestValidator.equals("reply's post_id matches")(reply.post_id)(post.id);
  TestValidator.equals("reply's user_id matches")(reply.user_id)(user.id);
  TestValidator.equals("reply content matches")(reply.content)(replyContent);
  TestValidator.predicate("created_at is present")(!!reply.created_at);
  TestValidator.predicate("updated_at is present")(!!reply.updated_at);
}

