import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate reply creation failure cases for the BBS comment-reply API.
 *
 * Business context:
 * Users must not be able to create a reply comment if required data is missing/invalid, or if not authenticated.
 * This test verifies server-side business logic for input validation and authentication.
 *
 * 1. Register a user to establish authentication context.
 * 2. Create a category (for the post).
 * 3. Create a post belonging to the new category.
 * 4. Add a top-level comment to the post (parent comment for replies).
 * 5. Attempt to create a reply with missing/empty content as the authenticated user (should throw a validation error).
 * 6. Attempt to create a reply as an unauthenticated user (should throw an authentication error).
 */
export async function test_api_bbs_test_create_reply_with_invalid_data_or_unauthorized(connection: api.IConnection) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, { body: {
    username: RandomGenerator.alphabets(8),
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: "P@ssw0rd!",
    role_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IBbsUsers.ICreate });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, { body: {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.content()()(),
  } });
  typia.assert(category);

  // 3. Create post
  const post = await api.functional.bbs.posts.post(connection, { body: {
    category_id: category.id,
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.content()()(),
  }});
  typia.assert(post);

  // 4. Add top-level parent comment to post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, { postId: post.id, body: {
    content: RandomGenerator.content()()(),
  }});
  typia.assert(comment);

  // 5. Try creating a reply with missing/empty content (validation error)
  await TestValidator.error("reply creation with empty content should fail")(() =>
    api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: comment.id,
      body: {
        content: ""
      }
    })
  );

  // 6. Try creating a reply as an unauthenticated user (auth error)
  // Clone the connection without auth headers
  const anonConnection = { ...connection, headers: { ...connection.headers } };
  delete anonConnection.headers.Authorization;

  await TestValidator.error("reply creation when unauthorized should fail")(() =>
    api.functional.bbs.comments.comments.postByCommentid(anonConnection, {
      commentId: comment.id,
      body: {
        content: RandomGenerator.content()()(),
      },
    })
  );
}

