import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test updating a reply (nested comment) as its author, and ensure access control.
 *
 * This scenario validates that only the original author (or privileged moderator) can update a reply comment. It covers full workflow:
 *
 * 1. Register two users (userA, userB)
 * 2. Create a category for posts
 * 3. Have userA create a post in that category
 * 4. Have userA add a top-level comment to the post
 * 5. Have userA add a reply (nested comment) to the comment
 * 6. UserA updates their reply; verify content changed, updated_at is newer, author (user_id) is unchanged
 * 7. Login as userB and attempt to update the same reply; confirm an authorization error is thrown
 */
export async function test_api_bbs_test_update_reply_with_valid_owner_and_data(connection: api.IConnection) {
  // 1. Register two users
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userBEmail = typia.random<string & tags.Format<"email">>();

  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: userAEmail,
      password: "Password123!",
      bio: "Author of the reply.",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: userBEmail,
      password: "Password123!",
      bio: "Another user.",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // *** This example assumes connection will act as the latest created user ***
  // Re-authenticate as userA for the main workflow (if needed/possible)

  // 2. Create a category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. UserA creates a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.paragraph()(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. UserA adds a top-level comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Parent comment for reply.",
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. UserA adds a reply to the comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: "This is the original reply content.",
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. UserA updates their reply
  const newContent = "Updated reply content by the owner.";
  const updatedReply = await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
    body: {
      content: newContent,
    } satisfies IBbsCommentReply.IUpdate,
  });
  typia.assert(updatedReply);
  TestValidator.equals("reply id remains the same")(updatedReply.id)(reply.id);
  TestValidator.equals("reply author remains unchanged")(updatedReply.user_id)(reply.user_id);
  TestValidator.equals("reply parent matches")(updatedReply.parent_id)(reply.parent_id);
  TestValidator.equals("reply content updated")(updatedReply.content)(newContent);
  TestValidator.predicate("updated_at is later")(updatedReply.updated_at > reply.updated_at);

  // 7. UserB attempts to update same reply (should fail with auth error)
  // Switch to userB context (assumes connection can switch; otherwise, need to re-authenticate as userB)
  // Typically handled by invoking login API, but here we simulate switching identity for the test purpose.
  // If direct login API is not present, this part relies on test runner to handle identity context.
  // For this test, attempt as userB and expect error:
  await TestValidator.error("Non-owner cannot update reply")(
    async () => {
      // Assume connection switches to userB
      // (Implementation note: in a real test, this requires a login mechanism, which is not present in listed SDKs;
      // If such API existed, we would call it here. If not possible, this part would be conditional/skipped.)
      await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
        body: {
          content: "Malicious update attempt by non-owner.",
        } satisfies IBbsCommentReply.IUpdate,
      });
    },
  );
}

