import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate that updating a reply fails when attempting invalid operations.
 *
 * This test ensures two failure scenarios for updating a reply (nested comment):
 * 1. Submitting an invalid payload (such as empty content), which must be rejected by the API
 * 2. Attempting to update a reply that was already soft-deleted, which should also fail
 *
 * Workflow:
 * 1. Register a user (to own all subsequent content)
 * 2. Create a category (for post organization)
 * 3. Create a post (under the created category, by the registered user)
 * 4. Add a top-level comment to the post
 * 5. Add a reply (nested comment) to the parent comment
 * 6. (Invalid content) Attempt to update the reply with empty content and ensure an error is thrown
 * 7. Delete the reply (soft-delete)
 * 8. Attempt to update the already-deleted reply and verify API rejects the edit
 */
export async function test_api_bbs_test_update_reply_with_invalid_content_or_deleted_reply(connection: api.IConnection) {
  // 1. Register a user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: RandomGenerator.alphaNumeric(10) + "@e2e.com",
      password: "1234e2eTest!",
      bio: null,
      role_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    }
  });
  typia.assert(category);

  // 3. Create post by the user in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    }
  });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(parentComment);

  // 5. Add a nested reply to the parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(reply);

  // 6. Try to update the reply with invalid (empty) content
  await TestValidator.error("empty content update should fail")(async () => {
    await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: "",
      },
    });
  });

  // 7. Delete the reply (soft-delete)
