import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Verify error response when an unauthorized user attempts to update a reply they do not own.
 *
 * This test covers two business-critical access control cases for threaded replies in a BBS:
 *   1) A user who did not author a reply attempts to edit it and should be denied;
 *   2) An unauthenticated (anonymous) request attempts update and must be declined.
 *
 * The test workflow:
 *   1. Register two users (user1: reply author; user2: unauthorized actor).
 *   2. Create a category for the post.
 *   3. As user1, create a post.
 *   4. As user1, create a comment on the post.
 *   5. As user1, create a reply to the comment (target for update attempt).
 *   6. As user2 (not the author), attempt to update user1's reply and expect error.
 *   7. As an unauthenticated client, attempt to update the reply and expect error.
 *
 * Both unauthorized attempts must yield proper permission or authentication errors. No update to the reply should occur.
 */
export async function test_api_bbs_test_update_reply_by_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Register two users
  //   a) We'll need distinct role_id for registration; generate random UUID (simulate standard user role)
  const user1RoleId = typia.random<string & tags.Format<"uuid">>();
  const user2RoleId = typia.random<string & tags.Format<"uuid">>();
  const user1Info = {
    username: RandomGenerator.alphabets(8),
    email: `${RandomGenerator.alphabets(8)}@test.com`,
    password: "Password123!",
    role_id: user1RoleId,
    bio: null,
  } satisfies IBbsUsers.ICreate;
  const user2Info = {
    username: RandomGenerator.alphabets(8),
    email: `${RandomGenerator.alphabets(8)}@test.com`,
    password: "Password123!",
    role_id: user2RoleId,
    bio: null,
  } satisfies IBbsUsers.ICreate;
  const user1 = await api.functional.bbs.users.post(connection, { body: user1Info });
  typia.assert(user1);
  const user2 = await api.functional.bbs.users.post(connection, { body: user2Info });
  typia.assert(user2);

  // 2. Create a category for post
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. User1 creates a post
  // (assume connection/session is associated with user1 after registration)
  // But if not, use user1 credentials (depends on platform's authentication design)
  // For this test, we use the connection as user1.
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(15),
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 4. User1 creates a comment on their post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // 5. User1 creates a reply to the comment (target reply)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(reply);

  // 6. As user2 (unauthorized), attempt to update user1's reply and expect permission error
  // Important: must switch authentication context to user2 (implementation-dependent)
  // For this test, emulate login by re-registering connection, or use user2's session
  // We'll assume connection can be used as user2 after registration
  // (if switching required, insert login step here)
  // Update reply content - expect error
  TestValidator.error("unauthorized user cannot update reply")(
    async () => {
      await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
        body: { content: "Unauthorized update attempt by another user." },
      });
    },
  );

  // 7. As unauthenticated client, attempt to update the reply and expect error
  // Remove authentication info from connection
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };
  TestValidator.error("unauthenticated user cannot update reply")(
    async () => {
      await api.functional.bbs.comments.comments.putByCommentidAndId(
        unauthenticatedConnection,
        {
          commentId: comment.id,
          id: reply.id,
          body: { content: "Anonymous update attempt." },
        },
      );
    },
  );
}

