import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test that the author of a reply can soft-delete their own reply comment.
 *
 * Business scenario:
 * - In a BBS (discussion board), only the author of a nested reply (comment on a comment) should be able to delete (soft-delete) their own reply.
 * - Deletion should not physically remove the reply from the database; instead, it must set the 'deleted_at' timestamp (soft-delete for moderation/audit).
 * - After deletion, the reply can't be accessed by regular users (i.e., not visible in reply list). Moderators or with direct access may see audit trails.
 *
 * Steps:
 * 1. Register a user
 * 2. Create a category (required for post)
 * 3. Create a post in that category
 * 4. Create a parent comment on the post
 * 5. Create a reply (nested comment) to the parent comment — this reply is the soft-delete target
 * 6. Delete the reply as its author
 * 7. Validate: (a) the API call succeeds, (b) the reply's `deleted_at` is set (soft-delete), (c) after delete, the reply is not accessible by regular users (e.g. further fetch/lookup errors)
 */
export async function test_api_bbs_test_delete_reply_with_owner_permission(connection: api.IConnection) {
  // 1. Register a user (need a role UUID to register)
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const userCreateInput: IBbsUsers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: RandomGenerator.alphaNumeric(10) + '@test.com',
    password: RandomGenerator.alphaNumeric(10),
    bio: RandomGenerator.alphaNumeric(20),
    role_id: roleId,
  };
  const user = await api.functional.bbs.users.post(connection, { body: userCreateInput });
  typia.assert(user);

  // 2. Create a category
  const categoryInput = {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.alphaNumeric(24),
  } satisfies bbsCategories.ICreate;
  const category = await api.functional.bbs.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // 3. Create a post
  const postInput = {
    category_id: category.id,
    title: RandomGenerator.alphaNumeric(16),
    content: RandomGenerator.alphaNumeric(32),
  } satisfies bbsPosts.ICreate;
  const post = await api.functional.bbs.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a parent comment on the post
  const parentCommentInput = {
    content: RandomGenerator.alphaNumeric(32),
    // top-level, so no parent_id
  } satisfies bbsComments.ICreate;
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: parentCommentInput,
  });
  typia.assert(parentComment);

  // 5. Create a reply (nested comment) to the parent comment
  const replyInput = {
    content: RandomGenerator.alphaNumeric(40),
  } satisfies IBbsCommentReply.ICreate;
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: replyInput,
  });
  typia.assert(reply);

  // 6. Delete the reply as its author
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id,
  });

  // 7. Since there is no fetch API for individual replies, as a postcondition we may assert that (a) author is able to delete, and (b) optionally attempt comment re-creation with same parent to verify thread integrity if needed (not possible here).
  // If there were an API to fetch the deleted reply, test that it returns not found or that its deleted_at is set. If only soft-delete is kept, a moderator would have to access it.
}

