import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test permission enforcement when deleting reply comments as unauthorized users.
 *
 * This test ensures that only the reply owner (or a moderator) is allowed to delete
 * a reply to a comment in the BBS system. Neither another user nor an unauthenticated
 * request should be able to perform the deletion operation.
 *
 * Steps:
 * 1. Register two users (user1 and user2).
 * 2. Create a category as user1.
 * 3. Create a post as user1 in that category.
 * 4. Add a base comment to the post as user1.
 * 5. Post a reply to that comment as user1.
 * 6. Attempt to delete the reply as user2: expect a permission (access denied) error.
 * 7. Attempt to delete the reply with no authentication: expect a permission (access denied) error.
 * 8. Confirm the reply still exists (not deleted).
 */
export async function test_api_bbs_test_delete_reply_by_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Register user1
  const user1RoleId = typia.random<string & tags.Format<"uuid">>();
  const user1 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: RandomGenerator.alphabets(8) + '@e2e.com',
      password: 'passwordUSER1',
      role_id: user1RoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user1);

  // 2. Register user2
  const user2RoleId = typia.random<string & tags.Format<"uuid">>();
  const user2 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: RandomGenerator.alphabets(8) + '@e2e.com',
      password: 'passwordUSER2',
      role_id: user2RoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user2);

  // 3. Create a category as user1
  // (Assume connection uses user1's session)
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.content()(1),
    },
  });
  typia.assert(category);

  // 4. Create a post as user1
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()()(1),
    },
  });
  typia.assert(post);

  // 5. Add a base comment as user1
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: 'This is a base comment',
    },
  });
  typia.assert(comment);

  // 6. Post a reply to that comment as user1
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: 'This is a reply to the base comment',
    },
  });
  typia.assert(reply);

  // 7. Attempt to delete the reply as user2 (simulate login as user2)
  // (Assume switching connection's user context is done by re-authenticating as user2)
  await api.functional.bbs.users.post(connection, {
    body: {
      username: user2.username,
      email: user2.email,
      password: 'passwordUSER2',
      role_id: user2RoleId,
    }
  });
  TestValidator.error('Only reply owner should be able to delete reply')(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
      });
    }
  );

  // 8. Attempt to delete the reply with no authentication (simulate logged-out state)
  const unauthConnection = { ...connection, headers: {} };
  TestValidator.error('Unauthenticated user should not be able to delete reply')(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(unauthConnection, {
        commentId: comment.id,
        id: reply.id,
      });
    }
  );

  // 9. (Optionally) Check that the reply still exists via another allowed read endpoint, e.g. by fetching parent comment's replies.
}

