import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate repeated deletion attempt on a reply comment after it's already soft-deleted.
 *
 * This test verifies the system's idempotency and soft-delete enforcement by ensuring an error is raised 
 * if attempting to delete a reply that's already been marked as deleted.
 *
 * Test procedure:
 * 1. Register a new user (for all subsequent actions).
 * 2. Create a new BBS category for the post to belong to.
 * 3. Create a post within that category.
 * 4. Add a top-level comment to that post.
 * 5. Add a reply as a child of that top-level comment.
 * 6. Delete the reply via API (should succeed, sets deleted_at).
 * 7. Attempt to delete the reply a second time (should fail with error for already deleted/not found).
 *
 * Steps 1-6 validate standard business flow.
 * Step 7 validates business logic that a reply can only be deleted once, and repeated
 * deletion attempts should return an error (e.g., not found or already deleted).
 */
export async function test_api_bbs_test_delete_reply_that_is_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate, 
  });
  typia.assert(user);

  // 2. Create a category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a post within the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a top-level comment
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(parentComment);

  // 5. Add a reply to the above comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: RandomGenerator.paragraph()(),
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. Soft-delete the reply (should succeed)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id,
  });

  // 7. Attempt to delete again (should error: already deleted or not found)
  await TestValidator.error("deleting already-deleted reply must fail")(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
        commentId: parentComment.id,
        id: reply.id,
      });
    },
  );
}

